def _candidate_quality_metadata() -> dict:
    return {
        "candidate_decision_quality_field_sources": {
            "expected_net_r": "fixture.expected_net_r",
            "probability": "fixture.probability",
            "confidence": "fixture.confidence",
            "fill_probability": "fixture.entry_quality_fill_probability",
            "entry_quality_fill_probability": "fixture.entry_quality_fill_probability",
            "limit_fillability_probability": "fixture.predecision_limit_fillability_probability",
            "source_completeness": "fixture.source_completeness",
        },
        "candidate_decision_quality_alias_status": "exact_materialized",
        "candidate_decision_quality_source_boundary": (
            "predecision_fixture_quality_fields_no_outcome"
        ),
        "execution_fill_probability_source": "predecision_limit_fillability",
        "execution_fill_probability_source_time_utc": (
            "2000-01-01T00:00:00+00:00"
        ),
        "execution_fill_probability_source_boundary": (
            "asof_candidate_fields_only_no_postdecision_path"
        ),
    }


def _strict_execution_fillability_fields(
    fill_probability: float,
    *,
    decision_time_utc: str = "2026-06-04T00:00:00+00:00",
) -> dict:
    return {
        "decision_time_utc": decision_time_utc,
        "predecision_limit_fillability_probability": fill_probability,
        "limit_fillability_probability": fill_probability,
        "execution_fill_probability": fill_probability,
        "execution_fill_probability_source": "predecision_limit_fillability",
        "execution_fill_probability_source_time_utc": (
            "2000-01-01T00:00:00+00:00"
        ),
        "execution_fill_probability_source_boundary": (
            "asof_candidate_fields_only_no_postdecision_path"
        ),
        "predecision_limit_fillability": {
            "fill_probability": fill_probability,
            "current_price_source_time_utc": "2000-01-01T00:00:00+00:00",
            "source_boundary": "asof_candidate_fields_only_no_postdecision_path",
        },
    }


def test_pending_exposure_prefers_limit_fillability_over_candidate_fill_probability():
    pending = PendingExposure.from_mapping(
        {
            "pending_id": "pending-limit-fillability",
            "symbol": "XAUUSD",
            "side": "LONG",
            "reserved_risk_pct": 0.25,
            "fill_probability": 0.95,
            "candidate_fill_probability": 0.95,
            "pending_limit_fillability_probability": 0.14,
            "pending_fill_probability_authority_class": "passive_limit_fillability",
        }
    )

    assert pending.fill_probability == 0.14
    assert pending.pending_fill_probability_authority_class == (
        "passive_limit_fillability"
    )
    assert pending.metadata["candidate_fill_probability"] == 0.95


def test_pending_exposure_does_not_use_candidate_fill_probability_as_order_fillability():
    pending = PendingExposure.from_mapping(
        {
            "pending_id": "pending-candidate-fill-only",
            "symbol": "XAUUSD",
            "side": "LONG",
            "reserved_risk_pct": 0.25,
            "fill_probability": 0.95,
            "candidate_fill_probability": 0.95,
            "scheduler_fill_probability": 0.95,
        }
    )

    assert pending.fill_probability is None
    assert (
        pending.pending_fill_probability_authority_class
        == "pending_order_fillability_missing"
    )
    assert pending.metadata["candidate_fill_probability"] == 0.95


def test_unused_pending_release_requires_runtime_replacement_authority():
    option = AllocatorOption(
        option_id="candidate:new-position:candidate-replace",
        source_type="candidate",
        action_class="new_position",
        candidate_id="candidate-replace",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="SHORT",
        requested_risk_pct=0.4,
        approved_risk_pct=0.4,
        risk_delta_pct=0.4,
        score=1.0,
        score_components={
            "pending_replacement_diagnostic": {
                "replacement_applied": True,
                "runtime_replacement_applied": False,
                "pending_replacement_causal_quality_gate_status": "passed",
                "release_pending_ids": ["pending-old"],
                "runtime_release_pending_ids": [],
                "release_candidates": [
                    {
                        "pending_id": "pending-old",
                        "cluster_key": "metals",
                        "reserved_risk_pct": 0.4,
                    }
                ],
                "portfolio_release_risk_pct": 0.4,
                "cluster_release_risk_pct": 0.4,
            }
        },
        decision_status="candidate",
        reason="fixture",
    )

    assert scheduler._unused_pending_release(
        option,
        cluster="metals",
        used_pending_ids=set(),
    ) == (0.0, 0.0, [])

    runtime_option = replace(
        option,
        score_components={
            "pending_replacement_diagnostic": {
                "replacement_applied": True,
                "runtime_replacement_applied": True,
                "pending_replacement_causal_quality_gate_status": "passed",
                "release_pending_ids": ["pending-old", "pending-unused"],
                "runtime_release_pending_ids": ["pending-old"],
                "release_candidates": [
                    {
                        "pending_id": "pending-old",
                        "cluster_key": "metals",
                        "reserved_risk_pct": 0.4,
                    },
                    {
                        "pending_id": "pending-unused",
                        "cluster_key": "metals",
                        "reserved_risk_pct": 0.9,
                    },
                ],
                "portfolio_release_risk_pct": 1.3,
                "cluster_release_risk_pct": 1.3,
            }
        },
    )

    assert scheduler._unused_pending_release(
        runtime_option,
        cluster="metals",
        used_pending_ids=set(),
    ) == (0.4, 0.4, ["pending-old"])


def test_scheduler_priority_repair_uses_raw_selector_origin_for_materialized_reduce():
    base_ladder = {
        "raw_selector_action": "reject",
        "effective_selector_action": "open-reduced-risk",
        "broker_cost_passed": True,
        "source_complete": True,
        "fill_floor_resolved_or_empty": True,
        "signed_package_authority_valid": True,
        "approved_risk_pct": 0.5,
        "terminal_vetoes": [],
        "tier_causes": [],
    }

    repaired = scheduler._risk_expression_ladder_after_scheduler_priority_repair(
        base_ladder,
        scheduler_priority_tier=0,
        scheduler_priority_reason="selector_reduced_new_entry_no_primary_trade_competitor",
    )

    assert repaired["ladder_tier"] == "full"
    assert repaired["tier_causes"] == [
        "signed_package_materialized_reduced_origin_full_risk_conditions_passed"
    ]
    assert repaired["raw_selector_reduced_origin"] is False
    assert repaired["signed_materialized_selector_reduced_origin"] is True
    assert repaired["selector_reduced_origin_full_risk_eligible"] is True

    unsigned = scheduler._risk_expression_ladder_after_scheduler_priority_repair(
        {**base_ladder, "signed_package_authority_valid": False},
        scheduler_priority_tier=0,
        scheduler_priority_reason="selector_reduced_new_entry_no_primary_trade_competitor",
    )

    assert unsigned["ladder_tier"] == "reduced"
    assert unsigned["tier_causes"] == [
        "signed_package_authority_missing_or_invalid"
    ]
    assert unsigned["signed_materialized_selector_reduced_origin"] is False


