def test_allocator_option_preserves_terminal_vs_soft_guard_contract() -> None:
    soft_guard_contract = {
        "terminal_vetoes": [],
        "soft_guard_vetoes": ["predecision_stop_hazard_guard"],
        "pool_eligible": True,
        "pool_status": "eligible",
        "pool_reason": "cost_passed_source_complete_signed_soft_guard_reallocation",
    }
    option = AllocatorOption(
        option_id="candidate:new-position:soft-guard",
        source_type="candidate",
        action_class="new_position",
        candidate_id="soft-guard",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.4,
        approved_risk_pct=0.4,
        risk_delta_pct=0.4,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "scheduler_terminal_vs_soft_guard": soft_guard_contract,
                "terminal_vetoes": [],
                "scheduler_terminal_vetoes": [],
                "reallocation_soft_guard_vetoes": [
                    "predecision_stop_hazard_guard"
                ],
                "scheduler_reallocation_soft_guard_vetoes": [
                    "predecision_stop_hazard_guard"
                ],
                "reallocation_soft_guard_pool_eligible": True,
                "reallocation_soft_guard_pool_status": "eligible",
                "reallocation_soft_guard_pool_reason": (
                    "cost_passed_source_complete_signed_soft_guard_reallocation"
                ),
                "reallocation_soft_guard_pool_terminal_vetoes": [],
            }
        },
        decision_status="candidate_admitted_reallocation_soft_guard_pool",
        reason="fixture",
    )

    assert scheduler._option_reallocation_soft_guard_vetoes(option) == (
        "predecision_stop_hazard_guard",
    )

    record = option.to_record()
    assert record["scheduler_terminal_vs_soft_guard"] == soft_guard_contract
    assert record["terminal_vetoes"] == []
    assert record["scheduler_terminal_vetoes"] == []
    assert record["reallocation_soft_guard_vetoes"] == [
        "predecision_stop_hazard_guard"
    ]
    assert record["scheduler_reallocation_soft_guard_vetoes"] == [
        "predecision_stop_hazard_guard"
    ]
    assert record["reallocation_soft_guard_pool_eligible"] is True
    assert record["reallocation_soft_guard_pool_status"] == "eligible"
    assert record["reallocation_soft_guard_pool_terminal_vetoes"] == []


def test_scheduler_uses_execution_fillability_for_new_entry_quality_and_score():
    decision_time = "2026-05-13T10:00:00+00:00"
    common = {
        "symbol": "XAUUSD",
        "side": "LONG",
        "action_intent": "new_position",
        "requested_risk_pct": 0.25,
        "selector_action": "trade",
        "selector_reason": "fixture_trade",
        "confidence": 0.85,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "no_leak_status": "pass",
        "cost_r": 0.03,
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
        "candidate_decision_quality_source_boundary": (
            "predecision_fixture_quality_fields_no_outcome"
        ),
        "execution_fill_probability_source": "predecision_limit_fillability",
    }
    high_paper_low_execution = {
        **common,
        "candidate_id": "paper-fill-high-execution-fill-low",
        "expected_net_r": 2.0,
        "candidate_probability": 0.90,
        "candidate_fill_probability": 0.95,
        "candidate_decision_quality_field_sources": {
            "expected_net_r": "fixture.expected_net_r",
            "probability": "fixture.candidate_probability",
            "fill_probability": "fixture.candidate_fill_probability",
            "source_completeness": "fixture.source_completeness",
        },
            "predecision_limit_fillability": {
                "available": True,
                "limit_marketable_at_decision": False,
                "limit_fillability_probability": 0.14,
                "current_price_source_time_utc": "2026-05-13T09:45:00+00:00",
                "source_boundary": "asof_candidate_fields_only_no_postdecision_path",
            },
    }
    lower_edge_executable = {
        **common,
        "candidate_id": "execution-fill-high",
        "expected_net_r": 0.80,
        "candidate_probability": 0.76,
        "candidate_fill_probability": 0.76,
        "candidate_decision_quality_field_sources": {
            "expected_net_r": "fixture.expected_net_r",
            "probability": "fixture.candidate_probability",
            "fill_probability": "fixture.candidate_fill_probability",
            "source_completeness": "fixture.source_completeness",
        },
            "predecision_limit_fillability": {
                "available": True,
                "limit_marketable_at_decision": False,
                "limit_fillability_probability": 0.92,
                "current_price_source_time_utc": "2026-05-13T09:45:00+00:00",
                "source_boundary": "asof_candidate_fields_only_no_postdecision_path",
            },
    }

    packet = build_scheduler_v4_packet(
        decision_window={
            "decision_window_id": "window:execution-fillability-score",
            "candidate_set_id": "set:execution-fillability-score",
            "asof_utc": decision_time,
            "candidates": [high_paper_low_execution, lower_edge_executable],
        },
        config={
            "enabled": True,
            "apply_to_execution": True,
            "portfolio_ceiling_pct": 1.0,
            "min_trade_score": 0.0,
            "zero_trade_score": 0.0,
            "dynamic_budget_quality_gate_enabled": True,
            "dynamic_budget_min_expected_net_r": 0.20,
            "dynamic_budget_min_probability": 0.55,
            "dynamic_budget_min_fill_probability": 0.80,
            "dynamic_budget_min_source_completeness": 0.65,
        },
    )

    paper_option = next(
        row
        for row in packet["all_options_preserved"]
        if row["candidate_id"] == "paper-fill-high-execution-fill-low"
    )
    executable_option = next(
        row
        for row in packet["all_options_preserved"]
        if row["candidate_id"] == "execution-fill-high"
    )

    assert packet["decision"]["selected_option"]["candidate_id"] == "execution-fill-high"
    assert paper_option["runtime_eligible"] is False
    assert (
        "scheduler_dynamic_budget_quality_floor_not_met:"
        "fill_probability_below_dynamic_allocator_floor"
    ) in paper_option["vetoes"]
    assert paper_option["score_components"]["entry_quality_fill_probability"] == 0.95
    assert paper_option["score_components"]["execution_fill_probability"] == 0.14
    assert paper_option["score_components"]["dynamic_budget_quality_gate"][
        "fill_probability"
    ] == 0.14
    assert paper_option["score_components"]["fill_probability_component"] == 0.014
    assert executable_option["score_components"]["execution_fill_probability"] == 0.92
    assert executable_option["runtime_eligible"] is True
    paper_ladder = paper_option["score_components"]["risk_expression_ladder"]
    executable_ladder = executable_option["score_components"]["risk_expression_ladder"]
    assert paper_ladder["ladder_tier"] == "diagnostic"
    assert any(
        "fill_probability_below_dynamic_allocator_floor" in cause
        for cause in paper_ladder["tier_causes"]
    )
    assert executable_ladder["ladder_tier"] == "full"
    assert executable_ladder["broker_cost_passed"] is True
    assert executable_ladder["source_complete"] is True
    assert (
        executable_option["score_components"]["candidate_decision_inputs"][
            "risk_expression_ladder"
        ]["ladder_tier"]
        == "full"
    )


