    assert signed_authority["status"] == "invalid_or_missing_signed_new_entry_authority"
    assert "router_refusal_fill_probability_below_floor" in signed_authority["failures"]
    assert replay_authority["failures"] == [
        "package_fill_floor_quality_not_met:"
        "fill_probability_below_execution_authority_floor"
    ]
    assert (
        replay_authority["package_replay_order_executable_candidate_use_allowed"]
        is False
    )
    assert replay_authority[
        "package_replay_order_executable_candidate_use_allowed_reason"
    ] == (
        "package_replay_executable_reduce_risk_authority_failed:"
        "package_fill_floor_quality_not_met:"
        "fill_probability_below_execution_authority_floor"
    )
    decision_inputs = option["score_components"]["candidate_decision_inputs"]
    assert option["package_new_entry_authority_valid"] is False
    assert decision_inputs["package_new_entry_authority_valid"] is False
    assert "router_refusal_fill_probability_below_floor" in decision_inputs[
        "package_new_entry_authority_failures"
    ]
    assert option["package_replay_order_executable_candidate_use_allowed"] is False
    assert option["package_replay_order_executable_candidate_use_allowed_reason"] == (
        "package_replay_executable_reduce_risk_authority_failed:"
        "package_fill_floor_quality_not_met:"
        "fill_probability_below_execution_authority_floor"
    )
    assert replay_authority["non_bypassable_fill_floor_failures"] == (
        "fill_probability_below_execution_authority_floor",
    )
    assert dynamic_gate["entry_quality_fill_probability"] == 0.93
    assert dynamic_gate["execution_fill_probability"] == 0.155868565
    assert dynamic_gate["package_fill_floor_bypass"]["failures"] == [
        "execution_fill_probability_below_route_floor"
    ]


