def test_signed_package_authority_rejects_tampered_fvg_poi_hash_after_restamp():
    decision_time = "2026-05-14T01:00:00+00:00"
    row = _signed_reduced_new_entry_metadata(
        {
            **_strict_execution_fillability_fields(
                0.80,
                decision_time_utc=decision_time,
            ),
            "candidate_id": "tampered-signed-fvg-poi-candidate",
            "decision_time_utc": decision_time,
            "symbol": "US30_CASH",
            "side": "LONG",
            "current_framework": "fvg_fill",
            "origin_family": "current_fvg_fill",
            "expected_net_r": 0.90,
            "probability": 0.80,
            "fill_probability": 0.80,
            "source_completeness": 1.0,
            "source_window_complete": True,
            "selector_action": "open-reduced-risk",
            "selector_reason": "unit_fvg_poi_signed_authority_tamper",
            "ultimate_candidate_package_open_reduced_risk_authority": {
                "applies": True,
                "allowed": True,
                "authority_family": "unit_fvg_poi_authority",
                "current_config_allowed": True,
            },
        }
    )
    authority = dict(row["ultimate_candidate_package_open_reduced_risk_authority"])
    payload = dict(authority["package_new_entry_authority_payload"])
    payload["poi_state"] = {
        **payload["poi_state"],
        "poi_state_hash_sha256": "0" * 64,
    }
    payload["poi_state_hash_sha256"] = "0" * 64
    authority_hash = scheduler.package_new_entry_authority_payload_hash_sha256(payload)
    authority["package_new_entry_authority_payload"] = payload
    authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD] = authority_hash
    authority["expected_package_new_entry_authority_hash_sha256"] = authority_hash
    row[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD] = authority_hash

    failures = scheduler.package_new_entry_authority_required_payload_atom_failures(
        payload
    )

    assert "signed_poi_state_hash_mismatch" in failures
    assert scheduler._immutable_package_new_entry_authority_payload_valid(
        row,
        authority,
    ) is False


