def test_required_payload_atom_validator_reports_precise_failures() -> None:
    row = _signed_source_bound_router_fixture(
        "required-payload-atom-contract",
        decision_time_utc="2026-06-04T18:50:00+00:00",
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    original_authority = row[authority_field]
    original_payload = original_authority[
        "package_new_entry_authority_payload"
    ]
    cases = (
        (("expected_net_r",), {}, "signed_expected_net_r_missing"),
        (("probability",), {}, "signed_probability_missing"),
        (
            ("fill_probability", "entry_quality_fill_probability"),
            {},
            "signed_fill_probability_or_entry_quality_fill_probability_missing",
        ),
        (("source_completeness",), {}, "signed_source_completeness_missing"),
        (
            ("execution_fill_probability",),
            {},
            "signed_execution_fill_probability_atom_missing",
        ),
        (
            ("limit_fillability_probability",),
            {},
            "signed_limit_fillability_probability_atom_missing",
        ),
        (
            ("predecision_limit_fillability_probability",),
            {},
            "signed_predecision_limit_fillability_probability_atom_missing",
        ),
        (
            (),
            {"execution_fill_probability_source": ""},
            "signed_execution_fill_probability_source_missing",
        ),
            (
                (),
                {"execution_fill_probability_source": "execution_fill_probability"},
                "signed_execution_fill_probability_source_unrecognized",
            ),
            (
                ("execution_fill_probability_authority_class",),
                {},
                "signed_execution_fill_probability_authority_class_invalid",
            ),
            (
                ("execution_fill_probability_source_time_utc",),
            {},
            "signed_execution_fill_probability_source_time_utc_atom_missing",
        ),
        (
            ("execution_fill_probability_source_boundary",),
            {},
            "signed_execution_fill_probability_source_boundary_atom_missing",
        ),
        (
            ("package_replay_order_executable_candidate_use_allowed",),
            {},
            "signed_order_executable_allowed_missing",
        ),
        (
            (
                "package_replay_order_executable_candidate_use_allowed_reason",
            ),
            {},
            "signed_order_executable_reason_missing",
        ),
        (
            ("package_replay_order_executable_authority_source",),
            {},
            "signed_order_executable_authority_source_missing",
        ),
    )

    for removed_fields, replacements, expected_failure in cases:
        payload = dict(original_payload)
        for field in removed_fields:
            payload.pop(field, None)
        payload.update(replacements)
        expected_failures = (expected_failure,)
        if expected_failure == "signed_execution_fill_probability_atom_missing":
            expected_failures += (
                "signed_order_executable_allowed_without_execution_fillability",
            )
        assert (
            scheduler.package_new_entry_authority_required_payload_atom_failures(
                payload
            )
            == expected_failures
        )
        authority = dict(original_authority)
        authority["package_new_entry_authority_payload"] = payload
        payload_hash = scheduler.package_new_entry_authority_payload_hash_sha256(
            payload
        )
        authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD] = payload_hash
        authority["expected_package_new_entry_authority_hash_sha256"] = payload_hash
        current_row = {**row, authority_field: authority}
        validation = scheduler.reduced_package_new_entry_authority_validation(
            current_row,
            selector_action=row["selector_action"],
            selector_reason=row["selector_reason"],
            action_intent="new_position",
        )

        assert expected_failure in validation["failures"]
        assert scheduler._immutable_package_new_entry_authority_payload_valid(
            current_row,
            authority,
        ) is False


