def test_structured_router_override_cannot_hide_invalid_predecessor_floors() -> None:
    packet, _config, _selector_reason = _router_close_reverse_override_packet()
    decision_inputs = dict(
        packet["all_options_preserved"][0]["score_components"][
            "candidate_decision_inputs"
        ]
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    authority = dict(decision_inputs[authority_field])
    predecessor_payload = dict(
        authority["package_new_entry_authority_predecessor_payload"]
    )
    successor_payload = dict(authority["package_new_entry_authority_payload"])
    for payload in (predecessor_payload, successor_payload):
        payload.update(
            {
                "expected_net_r": 0.10,
                "probability": 0.10,
                "fill_probability": 0.10,
                "entry_quality_fill_probability": 0.10,
                "execution_fill_probability": 0.10,
                "limit_fillability_probability": 0.10,
                "predecision_limit_fillability_probability": 0.10,
                "source_completeness": 0.10,
            }
        )
    predecessor_hash = scheduler.package_new_entry_authority_payload_hash_sha256(
        predecessor_payload
    )
    successor_hash = scheduler.package_new_entry_authority_payload_hash_sha256(
        successor_payload
    )
    authority.update(
        {
            "package_new_entry_authority_predecessor_payload": predecessor_payload,
            "package_new_entry_authority_predecessor_hash_sha256": predecessor_hash,
            "package_new_entry_authority_payload": successor_payload,
            scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD: successor_hash,
            "expected_package_new_entry_authority_hash_sha256": successor_hash,
        }
    )
    transition = dict(
        decision_inputs["package_new_entry_authority_action_transition"]
    )
    transition["predecessor_hash_sha256"] = predecessor_hash
    transition["successor_hash_sha256"] = successor_hash
    lifecycle_root = dict(decision_inputs["package_lifecycle_root_authority"])
    lifecycle_root["signed_authority_hash_sha256"] = successor_hash
    decision_inputs.update(
        {
            authority_field: authority,
            "package_new_entry_authority_action_transition": transition,
            "package_lifecycle_root_authority": lifecycle_root,
        }
    )

    failures = (
        scheduler.package_new_entry_authority_router_floor_override_proof_failures(
            decision_inputs,
            authority,
            successor_payload,
        )
    )

    assert (
        "router_refusal_close_reverse_floor_override_predecessor_floor_failures:"
        "expected_net_r,probability,fill_probability,source_completeness"
        in failures
    )


