def test_close_reverse_router_override_rejects_invalid_and_cross_instance_root() -> None:
    packet, config, selector_reason = _router_close_reverse_override_packet()
    valid_inputs = packet["all_options_preserved"][0]["score_components"][
        "candidate_decision_inputs"
    ]

    invalid_inputs = dict(valid_inputs)
    invalid_root = dict(valid_inputs["package_lifecycle_root_authority"])
    invalid_root.update({"allowed": False, "status": "blocked"})
    invalid_inputs["package_lifecycle_root_authority"] = invalid_root
    invalid_validation = scheduler.reduced_package_new_entry_authority_validation(
        invalid_inputs,
        selector_action="open-reduced-risk",
        selector_reason=selector_reason,
        action_intent="close_and_reverse",
        config=config,
    )

    cross_instance_inputs = dict(valid_inputs)
    cross_instance_root = dict(valid_inputs["package_lifecycle_root_authority"])
    cross_instance_root.update(
        {
            "candidate_id": "other-candidate",
            "canonical_replay_candidate_instance_key": (
                "other-candidate@@2026-06-04T19:00:00+00:00"
            ),
            "source_bound_replay_candidate_instance_key": (
                "other-candidate@@2026-06-04T19:00:00+00:00"
            ),
        }
    )
    cross_instance_inputs["package_lifecycle_root_authority"] = (
        cross_instance_root
    )
    cross_instance_validation = (
        scheduler.reduced_package_new_entry_authority_validation(
            cross_instance_inputs,
            selector_action="open-reduced-risk",
            selector_reason=selector_reason,
            action_intent="close_and_reverse",
            config=config,
        )
    )

    assert invalid_validation["valid"] is False
    assert (
        "router_refusal_close_reverse_floor_override_lifecycle_root_invalid"
        in invalid_validation["failures"]
    )
    assert cross_instance_validation["valid"] is False
    assert (
        "router_refusal_close_reverse_floor_override_lifecycle_root_instance_mismatch"
        in cross_instance_validation["failures"]
    )


