    assert option["runtime_eligible"] is True
    assert transition["allowed"] is True
    assert transition["predecessor_action_intent"] == "new_position"
    assert transition["successor_action_intent"] == "close_and_reverse"
    assert lifecycle_root["allowed"] is True
    assert lifecycle_root["release_kind"] == "opposite_open_close_reverse"
