    row = _signed_source_bound_router_fixture(
        "fake-hash-signed-fillability",
        execution_fill_probability=0.62,
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    authority = dict(row[authority_field])
    forged_payload = dict(authority["package_new_entry_authority_payload"])
    forged_payload["execution_fill_probability"] = 0.99
    forged_payload["execution_fill_probability_source"] = "forged.payload.fill"
    authority["package_new_entry_authority_payload"] = forged_payload
    row[authority_field] = authority
    row.update(
        {
            "predecision_limit_fillability_probability": 0.77,
            "limit_fillability_probability": 0.77,
            "execution_fill_probability": 0.77,
            "execution_fill_probability_source": "mutable.alias.fill",
        }
    )
    option = AllocatorOption(
        option_id="candidate:fake-hash-signed-fillability",
        source_type="new_candidate",
        action_class="new_position",
        candidate_id=row["candidate_id"],
        exposure_id=None,
        pending_id=None,
        symbol=row["symbol"],
        side=row["side"],
        requested_risk_pct=0.25,
        approved_risk_pct=0.10,
        risk_delta_pct=0.10,
        score=1.0,
        score_components={"candidate_decision_inputs": row},
        decision_status="candidate_ranked",
        reason="fake_hash_signed_fillability_fixture",
    )
    candidate = AllocatorCandidate.from_mapping(row)

    assert scheduler.package_new_entry_authority_payload_hash_sha256(
        forged_payload
    ) != authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD]
    signed_detail = scheduler._signed_payload_execution_fillability(row)
    assert signed_detail["claimed"] is True
    assert signed_detail["valid"] is False
    assert signed_detail["source"] == (
        scheduler.INVALID_SIGNED_EXECUTION_FILLABILITY_SOURCE
    )
    assert scheduler._execution_fillability_from_source(row) == (
        None,
        scheduler.INVALID_SIGNED_EXECUTION_FILLABILITY_SOURCE,
    )
    assert scheduler._option_execution_fill_probability(option, fallback=0.77) == (
        0.0,
        scheduler.INVALID_SIGNED_EXECUTION_FILLABILITY_SOURCE,
    )
    assert scheduler._candidate_execution_fill_probability(
        candidate,
        fallback=0.77,
    ) == (
        None,
        scheduler.INVALID_SIGNED_EXECUTION_FILLABILITY_SOURCE,
    )


