def test_frozen_package_authority_payload_reuses_exact_hash_and_blocks_mutation(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    row = _signed_source_bound_router_fixture("frozen-authority-hash-cache")
    authority = row[
        "ultimate_candidate_package_open_reduced_risk_authority"
    ]
    mutable_payload = copy.deepcopy(
        dict(authority["package_new_entry_authority_payload"])
    )
    frozen_payload = scheduler.freeze_package_new_entry_authority_payload(
        mutable_payload
    )
    expected_digest = scheduler._stable_sha256(dict(mutable_payload))
    scheduler.clear_package_new_entry_authority_payload_hash_cache()

    original_material = scheduler._stable_sha256_material
    calls = 0

    def counted_material(payload: object) -> str:
        nonlocal calls
        calls += 1
        return original_material(payload)

    monkeypatch.setattr(
        scheduler,
        "_stable_sha256_material",
        counted_material,
    )

    first_digest = scheduler.package_new_entry_authority_payload_hash_sha256(
        frozen_payload
    )
    second_digest = scheduler.package_new_entry_authority_payload_hash_sha256(
        frozen_payload
    )

    assert first_digest == second_digest == expected_digest
    assert calls == 1
    assert copy.deepcopy(frozen_payload) is frozen_payload
    with pytest.raises(TypeError, match="immutable package authority payload"):
        frozen_payload["expected_net_r"] = -9.0
    with pytest.raises(TypeError, match="immutable package authority payload"):
        frozen_payload[
            "source_bound_router_refusal_materialization_floors"
        ]["expected_net_r"] = -9.0
    assert (
        scheduler.package_new_entry_authority_payload_hash_sha256(frozen_payload)
        == expected_digest
    )
    assert calls == 1


