def test_stale_nested_quality_status_converges_with_final_normalized_atoms() -> None:
    row = _signed_package_authority_fixture_row(
        candidate_id="stale-nested-quality-now-converged"
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    unsigned_authority = _unsigned_authority_fixture(row[authority_field])
    row[authority_field] = unsigned_authority

    final_sources = dict(row["candidate_decision_quality_field_sources"])
    final_sources["execution_fill_probability"] = (
        "unit_test.predecision.predecision_limit_fillability_probability"
    )
    row["candidate_decision_quality_field_sources"] = final_sources
    row["candidate_decision_quality_alias_status"] = "mismatch"
    row["candidate_decision_quality_alias_mismatches"] = []

    stale_nested = dict(row["candidate_decision_quality"])
    for field in (
        "execution_fill_probability",
        "limit_fillability_probability",
        "predecision_limit_fillability_probability",
    ):
        stale_nested.pop(field, None)
    stale_sources = dict(
        stale_nested.get("candidate_decision_quality_field_sources")
        or stale_nested.get("field_sources")
        or {}
    )
    stale_sources.pop("execution_fill_probability", None)
    stale_sources.pop("limit_fillability_probability", None)
    stale_nested["field_sources"] = stale_sources
    stale_nested["candidate_decision_quality_field_sources"] = stale_sources
    stale_nested["alias_status"] = "mismatch"
    stale_nested["candidate_decision_quality_alias_status"] = "mismatch"
    stale_nested["alias_mismatches"] = []
    stale_nested["candidate_decision_quality_alias_mismatches"] = []
    row["candidate_decision_quality"] = stale_nested

    normalized = scheduler._normalized_candidate_quality_fields(row)
    normalized_envelope = normalized["candidate_decision_quality"]

    assert normalized["candidate_decision_quality_alias_mismatches"] == []
    assert normalized["candidate_decision_quality_alias_status"] == (
        "exact_materialized"
    )
    assert normalized["limit_fillability_probability"] == 0.72
    assert normalized["predecision_limit_fillability_probability"] == 0.72
    assert normalized["candidate_decision_quality_field_sources"] == final_sources
    assert normalized_envelope["field_sources"] == final_sources
    assert normalized_envelope["candidate_decision_quality_field_sources"] == (
        final_sources
    )
    assert normalized_envelope["alias_status"] == "exact_materialized"
    assert normalized_envelope["candidate_decision_quality_alias_status"] == (
        "exact_materialized"
    )

    row[authority_field] = scheduler.stamp_package_new_entry_authority(
        row,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        authority=unsigned_authority,
        action_intent="new_position",
    )
    payload = row[authority_field]["package_new_entry_authority_payload"]
    current_failures = scheduler._current_signed_payload_input_failures(row, payload)
    validation = scheduler.reduced_package_new_entry_authority_validation(
        row,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
    )

    assert payload["execution_fill_probability"] == 0.72
    assert payload["limit_fillability_probability"] == 0.72
    assert payload["candidate_decision_quality_alias_status"] == (
        "exact_materialized"
    )
    assert not any(
        failure.startswith("current_signed_quality_mismatch:")
        for failure in current_failures
    )
    assert validation["valid"] is True

    conflicted = dict(row)
    conflicted_nested = dict(stale_nested)
    conflicted_sources = dict(stale_sources)
    conflicted_sources["probability"] = "unit_test.drifted.probability"
    conflicted_nested["field_sources"] = conflicted_sources
    conflicted_nested["candidate_decision_quality_field_sources"] = (
        conflicted_sources
    )
    conflicted["candidate_decision_quality"] = conflicted_nested
    conflicted_normalized = scheduler._normalized_candidate_quality_fields(conflicted)

    assert conflicted_normalized["candidate_decision_quality_alias_status"] == (
        "mismatch"
    )
    assert any(
        mismatch.startswith("field_sources:probability:")
        for mismatch in conflicted_normalized[
            "candidate_decision_quality_alias_mismatches"
        ]
    )


