def candidate(
    candidate_id: str,
    symbol: str,
    side: str = "LONG",
    *,
    action_intent: str = "new_position",
    risk_pct: float | None = 0.25,
    ev_r: float | None = 0.8,
    probability: float | None = 0.65,
    confidence: float = 0.8,
    uncertainty: float = 0.2,
    confluence_action: str | None = "FOLLOW",
    confluence_strength: float = 0.8,
    avoid_invalidation_type: str | None = None,
    thesis_improvement: float | None = None,
    no_leak_status: str = "pass",
    fill_probability: float = 0.8,
) -> AllocatorCandidate:
    return AllocatorCandidate(
        candidate_id=candidate_id,
        symbol=symbol,
        side=side,
        action_intent=action_intent,
        requested_risk_pct=risk_pct,
        ev_r=ev_r,
        probability=probability,
        confidence=confidence,
        uncertainty=uncertainty,
        fill_probability=fill_probability,
        source_completeness=1.0,
        source_completeness_status="complete",
        evidence_class="source_bound_decision_time_fixture",
        no_leak_status=no_leak_status,
        confluence_action=confluence_action,
        confluence_strength=confluence_strength,
        confluence_confidence=confidence,
        confluence_reliability=0.8,
        avoid_invalidation_type=avoid_invalidation_type,
        cost_r=0.05,
        selected_cell_risk_pct=risk_pct,
        thesis_id=f"thesis:{candidate_id}",
        thesis_improvement=thesis_improvement,
        metadata={
            **_candidate_quality_metadata(),
            "predecision_limit_fillability_probability": fill_probability,
            "pretrade_cost_packet_status": "PASSED",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "cost_authority": "broker_calibrated_replay_cost",
        },
    )


def packet_for(window: DecisionWindow, **config_overrides):
    config = SchedulerV4Config(
        enabled=True,
        apply_to_execution=True,
        live_activation_allowed=False,
        **config_overrides,
    )
    return build_scheduler_v4_packet(decision_window=window, config=config)


def _source_stable_occurrence_row(
    candidate_id: str,
    symbol: str,
    *,
    decision_time: str,
    entry_price: float,
    stop_loss: float,
    take_profit: float,
    emission_ordinal: int = 0,
    expected_net_r: float = 1.0,
    probability: float = 0.85,
    fill_probability: float = 0.90,
) -> dict:
    """Build identity through the producer contract from bound fixture rows."""

    parsed_decision_time = datetime.fromisoformat(
        decision_time.replace("Z", "+00:00")
    ).astimezone(timezone.utc)
    source_hashes: dict[str, str] = {}
    source_association: dict[str, dict] = {}
    for index, timeframe in enumerate(("D1", "H4", "H1", "M15")):
        predecessor = parsed_decision_time - timedelta(hours=2, minutes=index)
        successor = predecessor + timedelta(minutes=15)
        witness = {
            "witness_type": "observed_successor_open_utc_upper_bound",
            "completion_semantics": "next_bound_open_not_exact_close",
            "timeframe": timeframe,
            "predecessor_source_ordinal": 0,
            "successor_source_ordinal": 1,
            "predecessor_open_utc": predecessor.isoformat(),
            "successor_open_utc": successor.isoformat(),
            "successor_market_values_consumed": False,
        }
        source_row = {
            "time": predecessor.isoformat(),
            "open": entry_price,
            "high": max(entry_price, take_profit),
            "low": min(entry_price, stop_loss),
            "close": entry_price,
            "wave21_completed_bar_witness": witness,
        }
        source_hashes[timeframe] = hashlib.sha256(
            json.dumps(
                {"timeframe": timeframe, "rows": [source_row]},
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        source_association[timeframe] = {
            "row_count": 1,
            "last_open_utc": predecessor.isoformat(),
            "completion_witness": witness,
        }

    risk_reward_ratio = abs(take_profit - entry_price) / abs(
        entry_price - stop_loss
    )
    row = {
        **_candidate_quality_metadata(),
        "candidate_id": candidate_id,
        "candidate_id_source": "candidate_id",
        "symbol": symbol,
        "side": "LONG",
        "direction": "LONG",
        "origin_family": "displacement_continuation",
        "candidate_origin_family": "origin_displacement_continuation",
        "framework": "displacement_continuation",
        "timeframe": "M15",
        "decision_time_utc": decision_time,
        "candidate_source_safe_decision_time_utc": decision_time,
        "entry_price": entry_price,
        "entry_reference": entry_price,
        "stop_loss": stop_loss,
        "stop_or_invalidation": stop_loss,
        "take_profit_1": take_profit,
        "target_reference": take_profit,
        "risk_reward_ratio": risk_reward_ratio,
        "rr": risk_reward_ratio,
        "trade_parameters": {
            "direction": "LONG",
            "entry_price": entry_price,
            "stop_loss": stop_loss,
            "take_profit_1": take_profit,
            "risk_reward_ratio": risk_reward_ratio,
        },
        "live_generation_status": "generated_live_asof",
        "candidate_lineage_authority": (
            "producer_bound_not_independently_reverified"
        ),
        "candidate_source_slice_hashes_by_timeframe": source_hashes,
        "candidate_source_row_association": source_association,
        "action_intent": "new_position",
        "requested_risk_pct": 0.25,
        "selected_cell_risk_pct": 0.25,
        "ev_r": expected_net_r,
        "expected_net_r": expected_net_r,
        "probability": probability,
        "confidence": 0.80,
        "uncertainty": 0.20,
        "fill_probability": fill_probability,
        "entry_quality_fill_probability": fill_probability,
        "predecision_limit_fillability_probability": fill_probability,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "evidence_class": "source_bound_decision_time_fixture",
        "no_leak_status": "pass",
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
    }
    fingerprint = candidate_source_safe_fingerprint_from_fields(row)
    assert fingerprint
    row[CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD] = fingerprint
    row[CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD] = fingerprint
    row[CANDIDATE_EMISSION_ORDINAL_FIELD] = emission_ordinal
    row[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD] = candidate_emission_anchor_key(
        fingerprint,
        emission_ordinal,
    )
    occurrence_key = candidate_occurrence_key_from_fields(row)
    assert occurrence_key
    row[CANDIDATE_OCCURRENCE_KEY_FIELD] = occurrence_key
    return row


