    expected_error = "scheduler_pristine_status_mismatch"
    if mutation == "rejected":
        corrupted["rejected_alternatives"] = []
        expected_error = "scheduler_pristine_rejected_alternatives_mismatch"
    elif mutation == "config":
        corrupted["config"]["min_trade_score"] = 999.0
        expected_error = "scheduler_pristine_config_projection_mismatch"
    elif mutation == "status":
        corrupted["status"] = "forged_status"
    else:
        corrupted["decision_window_id"] = "forged_window"
        expected_error = "scheduler_pristine_window_identity_mismatch:decision_window_id"
    with pytest.raises(ValueError, match=expected_error):
        scheduler._scheduler_pristine_sidecar_from_trace(corrupted, trace)


