def test_package_row_missing_action_intent_is_vetoed_not_defaulted_to_new_position():
    parsed = AllocatorCandidate.from_mapping(
        {
            "candidate_id": "package-missing-action",
            "symbol": "XAUUSD",
            "side": "LONG",
            "risk_pct": 0.25,
            "candidate_expected_net_r": 0.91,
            "probability": 0.82,
            "fill_probability": 0.70,
            "source_completeness": 1.0,
            "source_completeness_status": "complete",
            "no_leak_status": "pass",
            "selector_action": "open-reduced-risk",
            "selector_reason": (
                "ultimate_candidate_package_positive_predecision_router_refusal_open_reduced_risk"
            ),
            "scheduler_materialization_requires_explicit_action_intent": True,
            "ultimate_package_source_bound_candidate_use_allowed": True,
            "ultimate_package_admission_sleeve_match_count": 1,
            "ultimate_package_matched_sleeve_count": 1,
            "package_replay_executable_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed_reason": (
                "broker_cost_and_scheduler_action_executable"
            ),
            "pretrade_cost_packet_status": "PASSED",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "cost_authority": "broker_calibrated_replay_cost",
        }
    )
    assert parsed.action_intent == "invalid_action_intent:missing_scheduler_action_intent"

    packet = build_scheduler_v4_packet(
        decision_window={
            "decision_window_id": "window:package-missing-action",
            "candidate_set_id": "set:package-missing-action",
            "asof_utc": "2026-06-04T00:00:00+00:00",
            "candidates": [parsed.metadata],
        },
        config={"enabled": True, "apply_to_execution": True},
    )

    option = next(
        row
        for row in packet["all_options_preserved"]
        if row["candidate_id"] == "package-missing-action"
    )
    assert option["decision_status"] == "candidate_vetoed"
    assert (
        "invalid_scheduler_action_intent:invalid_action_intent:missing_scheduler_action_intent"
        in option["vetoes"]
    )
    assert packet["decision"]["selected_action_class"] == "zero_trade"


def test_package_executable_authority_accepts_no_outcome_predecision_boundary():
    base = candidate(
        "candidate:no-outcome-boundary",
        "XAUUSD",
        ev_r=1.05,
        probability=0.82,
        fill_probability=0.92,
    )
    quality_sources = {
        "expected_net_r": "packets.candidate_ev_r-minus-packets.broker_calibrated_expected_cost_r",
        "probability": "packets.candidate_probability",
        "confidence": "candidate.confidence",
        "fill_probability": "candidate.fill_probability",
        "source_completeness": "candidate.source_completeness",
    }
    broker_cost_rank = {
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "hard_veto_reason": None,
    }
    allowed_candidate = replace(
        base,
        expected_net_r=0.99,
        metadata={
            **base.metadata,
            "package_replay_executable_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed_reason": (
                "broker_cost_and_scheduler_action_executable"
            ),
            "candidate_decision_quality_field_sources": quality_sources,
                "candidate_decision_quality_alias_status": "materialized",
                "candidate_decision_quality_source_boundary": (
                    "predecision_packet_selector_event_and_candidate_feature_signal_no_outcome_fields"
                ),
                "source_bound_package_candidate_use_allowed": True,
                "ultimate_package_admission_sleeve_match_count": 1,
                "ultimate_package_matched_member_axis_ids": [
                    "scheduler_lifecycle_core|XAUUSD|LONG"
                ],
            },
        )

    allowed, reason, source = scheduler._candidate_package_executable_authority(
        allowed_candidate,
        broker_cost_rank,
    )

    assert allowed is True
    assert reason == "broker_cost_and_scheduler_action_executable"
    assert source == "explicit_package_replay_executable_or_replay_candidate_use_allowed_now"

    forbidden_candidate = replace(
        allowed_candidate,
        metadata={
            **allowed_candidate.metadata,
            "candidate_decision_quality_source_boundary": (
                "post_trade_actual_outcome_label"
            ),
        },
    )
    allowed, reason, source = scheduler._candidate_package_executable_authority(
        forbidden_candidate,
        broker_cost_rank,
    )

    assert allowed is False
    assert "candidate_decision_quality_source_boundary_not_predecision" in reason
    assert source == "explicit_package_replay_executable_revalidated_failed"


def test_package_executable_authority_rederives_stale_partially_materialized_alias_status():
    base = candidate(
        "stale-partial-quality",
        "AUDJPY",
        ev_r=1.24,
        probability=0.91,
        confidence=None,
        fill_probability=0.92,
    )
    quality_sources = {
        "expected_net_r": "scheduler_option.candidate_decision_inputs.expected_net_r",
        "probability": "scheduler_option.candidate_decision_inputs.probability",
        "fill_probability": "scheduler_option.candidate_decision_inputs.fill_probability",
        "source_completeness": "scheduler_option.candidate_decision_inputs.source_completeness",
    }
    broker_cost_rank = {
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "hard_veto_reason": None,
    }

    for alias_status in ("partially_materialized", "partial_materialized"):
        stale_candidate = replace(
            base,
            expected_net_r=1.20,
            metadata={
                **base.metadata,
                "package_replay_executable_candidate_use_allowed": False,
                "package_replay_executable_candidate_use_allowed_reason": (
                    "explicit_package_replay_executable_rejected:"
                    "candidate_decision_quality_provenance_missing:"
                    f"candidate_decision_quality_alias_status:{alias_status}"
                ),
                "candidate_decision_quality_field_sources": quality_sources,
                "candidate_decision_quality_alias_status": alias_status,
                "candidate_decision_quality_source_boundary": (
                    "predecision_packet_selector_event_and_candidate_feature_signal_no_outcome_fields"
                ),
                "source_bound_package_candidate_use_allowed": True,
                "ultimate_package_admission_sleeve_match_count": 1,
                "ultimate_package_matched_member_axis_ids": [
                    "scheduler_lifecycle_core|AUDJPY|LONG"
                ],
            },
        )

        assert scheduler._candidate_quality_provenance_failures(stale_candidate) == ()
        allowed, reason, source = scheduler._candidate_package_executable_authority(
            stale_candidate,
            broker_cost_rank,
        )

        assert allowed is True
        assert reason == "derived_predecision_quality_source_and_broker_cost_authority"
        assert source == "derived_after_selector_reduce_risk_materialization_self_lock"
    assert (
        scheduler._candidate_execution_authority_vetoes(
            stale_candidate,
            broker_cost_rank,
        )
        == ()
    )


def test_package_executable_authority_labels_explicit_false_broker_cost_refusal():
    base = candidate(
        "broker-cost-refused-package",
        "AUDJPY",
        ev_r=1.24,
        probability=0.91,
        confidence=None,
        fill_probability=0.92,
    )
    quality_sources = {
        "expected_net_r": "scheduler_option.candidate_decision_inputs.expected_net_r",
        "probability": "scheduler_option.candidate_decision_inputs.probability",
        "fill_probability": "scheduler_option.candidate_decision_inputs.fill_probability",
        "source_completeness": "scheduler_option.candidate_decision_inputs.source_completeness",
    }
    refused_candidate = replace(
        base,
        expected_net_r=1.20,
        metadata={
            **base.metadata,
            "package_replay_executable_candidate_use_allowed": False,
            "package_replay_executable_candidate_use_allowed_reason": (
                "broker_cost_packet_refused:spread_r_exceeds_selected_cell_limit"
            ),
            "candidate_decision_quality_field_sources": quality_sources,
            "candidate_decision_quality_alias_status": "exact_materialized",
            "candidate_decision_quality_source_boundary": (
                "predecision_packet_selector_event_and_candidate_feature_signal_no_outcome_fields"
            ),
            "source_bound_package_candidate_use_allowed": True,
            "ultimate_package_source_bound_candidate_use_allowed": True,
            "ultimate_package_admission_sleeve_match_count": 1,
        },
    )
    broker_cost_rank = {
        "pretrade_cost_packet_status": "REFUSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "hard_veto_reason": (
            "broker_cost_packet_refused:spread_r_exceeds_selected_cell_limit"
        ),
    }

    allowed, reason, source = scheduler._candidate_package_executable_authority(
        refused_candidate,
        broker_cost_rank,
    )

    assert allowed is False
    assert (
        reason
        == "broker_cost_not_executable:"
        "broker_cost_packet_refused:spread_r_exceeds_selected_cell_limit"
    )
    assert source == "broker_cost_authority_blocked"


