def test_optional_confidence_default_projection_aliases_canonicalize_atomically():
    default_source = scheduler.DEFAULT_MISSING_CONFIDENCE_SOURCE
    row = {
        "confidence": 0.55,
        "candidate_confidence": 0.55,
        "confidence_missing_degraded_default_applied": True,
        "candidate_decision_quality_alias_status": "mismatch",
        "candidate_decision_quality_alias_mismatches": [
            "field_sources:confidence:row.candidate_decision_quality_vs_canonical",
            "field_sources:confidence:row_vs_canonical",
        ],
        "candidate_decision_quality_field_sources": {
            "confidence": "candidate.candidate_confidence",
        },
        "candidate_decision_quality_optional_provenance_warnings": [
            f"confidence_source_inferred:{default_source}",
            "confidence_missing_degraded_default_applied",
        ],
        "candidate_decision_quality": {
            "confidence": 0.55,
            "candidate_confidence": 0.55,
            "confidence_missing_degraded_default_applied": True,
            "candidate_decision_quality_alias_status": "exact_materialized",
            "candidate_decision_quality_field_sources": {
                "confidence": default_source,
            },
            "candidate_decision_quality_optional_provenance_warnings": [
                f"confidence_source_inferred:{default_source}",
                "confidence_missing_degraded_default_applied",
            ],
        },
    }

    normalized = scheduler._normalized_candidate_quality_fields(row)

    assert normalized["candidate_decision_quality_field_sources"]["confidence"] == (
        default_source
    )
    assert normalized["candidate_decision_quality_alias_mismatches"] == []
    assert normalized["candidate_decision_quality_alias_status"] == "exact_materialized"
    assert normalized["candidate_decision_quality"]["field_sources"][
        "confidence"
    ] == default_source


