def _unsigned_authority_fixture(authority: dict) -> dict:
    """Return fixture authority intent without prior signed payload fields."""

    return {
        key: value
        for key, value in dict(authority or {}).items()
        if not key.startswith("package_new_entry_authority_")
        and key != scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD
        and key != "expected_package_new_entry_authority_hash_sha256"
        and key != "uses_outcome_fields"
    }


