def test_signed_payload_canonicalizes_equivalent_complete_source_status_aliases():
    complete = _signed_package_authority_fixture_row(
        candidate_id="canonical-complete-source-status"
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    complete_authority = complete[authority_field]

    source_present = copy.deepcopy(complete)
    source_present["source_completeness_status"] = "source_completeness_present"
    source_present["candidate_decision_quality"]["source_completeness_status"] = (
        "source_completeness_present"
    )
    source_present_authority = scheduler.stamp_package_new_entry_authority(
        source_present,
        selector_action=source_present["selector_action"],
        selector_reason=source_present["selector_reason"],
        authority=_unsigned_authority_fixture(complete_authority),
        action_intent="new_position",
    )

    assert complete_authority["package_new_entry_authority_payload"][
        "source_completeness_status"
    ] == "complete"
    assert source_present_authority["package_new_entry_authority_payload"][
        "source_completeness_status"
    ] == "complete"
    assert source_present_authority[
        scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD
    ] == complete_authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD]

    incomplete = copy.deepcopy(source_present)
    incomplete["source_completeness_status"] = "incomplete"
    incomplete["candidate_decision_quality"]["source_completeness_status"] = (
        "incomplete"
    )
    incomplete_authority = scheduler.stamp_package_new_entry_authority(
        incomplete,
        selector_action=incomplete["selector_action"],
        selector_reason=incomplete["selector_reason"],
        authority=_unsigned_authority_fixture(complete_authority),
        action_intent="new_position",
    )
    assert incomplete_authority["package_new_entry_authority_payload"][
        "source_completeness_status"
    ] == "incomplete"
    assert incomplete_authority[
        scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD
    ] != complete_authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD]


