def test_controlled_action_transition_preserves_every_non_action_payload_atom():
    row = _signed_package_authority_fixture_row(
        candidate_id="signed-controlled-action-transition"
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    predecessor = row[authority_field]
    successor, transition = scheduler.transition_package_new_entry_authority_action(
        row,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        authority=predecessor,
        predecessor_action_intent="new_position",
        successor_action_intent="same_direction_scale_in",
    )

    assert successor is not None
    assert transition["allowed"] is True
    predecessor_payload = predecessor["package_new_entry_authority_payload"]
    successor_payload = successor["package_new_entry_authority_payload"]
    assert successor_payload["target_action_intent"] == "same_direction_scale_in"
    assert successor_payload["scope"] == (
        "selector_reduced_risk_to_scheduler_same_direction_scale_in"
    )
    for key in set(predecessor_payload) | set(successor_payload):
        if key not in scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_ACTION_TRANSITION_FIELDS:
            assert predecessor_payload.get(key) == successor_payload.get(key)
    assert successor[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD] != predecessor[
        scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD
    ]

    transitioned_row = {**row, authority_field: successor}
    validation = scheduler.reduced_package_new_entry_authority_validation(
        transitioned_row,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="same_direction_scale_in",
    )
    assert validation["valid"] is True


