def test_owner_approved_family_root_releases_only_its_exact_stale_false_lock():
    base = candidate(
        "owner-approved-xau-root",
        "XAUUSD",
        side="SHORT",
        ev_r=1.18,
        probability=0.88,
        fill_probability=0.90,
    )
    decision_time = "2025-11-03T09:30:00+00:00"
    instance_key = f"{base.candidate_id}@@{decision_time}"
    sleeve_id = (
        "fpsc_scheduler_lifecycle_merge_sleeve__broader_origin__"
        "displacement_continuation__short"
    )
    registry_row_sha256 = "3dbe5a25b5ca98140881dd204b5189d0c032ba565c6ea9690ee3715fc7b99005"
    payload = {
        "schema": "gtos.wave21.owner_approved_package_family_root.v1",
        "policy_id": "owner_xau_displacement_short_family_root_v1",
        "evidence_class": "owner_approved_research_family_root_not_exact_member_axis",
        "source_boundary": (
            "predecision_owner_approved_research_family_root_no_outcome_fields_"
            "live_broker_authority_false"
        ),
        "symbol": "XAUUSD",
        "side": "SHORT",
        "origin_family": "displacement_continuation",
        "candidate_id": base.candidate_id,
        "decision_time_utc": decision_time,
        "canonical_replay_candidate_instance_key": instance_key,
        "source_bound_replay_candidate_instance_key": instance_key,
        "required_sleeve_id": sleeve_id,
        "required_registry_row_sha256": registry_row_sha256,
        "required_package_role": "scheduler_lifecycle_core",
        "research_only": True,
        "live_broker_authority": False,
        "uses_outcome_fields": False,
    }
    root_metadata = {
        **base.metadata,
        "candidate_id": base.candidate_id,
        "decision_time_utc": decision_time,
        "symbol": "XAUUSD",
        "side": "SHORT",
        "origin_family": "origin_displacement_continuation",
        "candidate_instance_identity_status": "materialized",
        "canonical_replay_candidate_instance_key": instance_key,
        "source_bound_replay_candidate_instance_key": instance_key,
        "ultimate_package_admission_sleeve_match_count": 1,
        "ultimate_package_combined_source_bound_signal_r_sum": 1.0,
        "ultimate_package_matched_sleeve_authorities": [
            {
                "sleeve_id": sleeve_id,
                "row_hash_sha256": registry_row_sha256,
                "package_role": "scheduler_lifecycle_core",
            }
        ],
        "ultimate_package_owner_approved_family_root_admission_allowed": True,
        "ultimate_package_owner_approved_family_root_admission_payload": payload,
        "ultimate_package_owner_approved_family_root_admission_hash_sha256": (
            scheduler._stable_sha256(payload)
        ),
        "package_replay_executable_candidate_use_allowed": False,
        "package_replay_executable_candidate_use_allowed_reason": (
            "explicit_package_replay_executable_rejected:"
            "source_bound_package_candidate_use_not_allowed"
        ),
    }
    rooted = replace(
        base,
        decision_time_utc=decision_time,
        expected_net_r=1.12,
        ultimate_package_admission_sleeve_match_count=1,
        ultimate_package_combined_source_bound_signal_r_sum=1.0,
        metadata=root_metadata,
    )
    broker_cost_rank = {
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "hard_veto_reason": None,
    }

    assert scheduler._owner_approved_family_root_admission_valid(rooted.metadata)
    allowed, reason, source = scheduler._candidate_package_executable_authority(
        rooted,
        broker_cost_rank,
    )
    assert allowed is True
    assert reason == "derived_predecision_quality_source_and_broker_cost_authority"
    assert source == "derived_after_owner_approved_family_root_self_lock"

    tampered_metadata = copy.deepcopy(root_metadata)
    tampered_payload = dict(tampered_metadata[
        "ultimate_package_owner_approved_family_root_admission_payload"
    ])
    tampered_payload["required_registry_row_sha256"] = "f" * 64
    tampered_metadata[
        "ultimate_package_owner_approved_family_root_admission_payload"
    ] = tampered_payload
    tampered_metadata[
        "ultimate_package_owner_approved_family_root_admission_hash_sha256"
    ] = scheduler._stable_sha256(tampered_payload)
    tampered = replace(rooted, metadata=tampered_metadata)
    assert not scheduler._owner_approved_family_root_admission_valid(tampered.metadata)
    allowed, reason, _source = scheduler._candidate_package_executable_authority(
        tampered,
        broker_cost_rank,
    )
    assert allowed is False
    assert reason == (
        "explicit_package_replay_executable_rejected:"
        "source_bound_package_candidate_use_not_allowed"
    )

    unrelated_lock = replace(
        rooted,
        metadata={
            **root_metadata,
            "package_replay_executable_candidate_use_allowed_reason": (
                "daily_loss_lockout"
            ),
        },
    )
    allowed, reason, _source = scheduler._candidate_package_executable_authority(
        unrelated_lock,
        broker_cost_rank,
    )
    assert allowed is False
    assert reason == "daily_loss_lockout"


