def test_package_new_entry_authority_hash_binds_exact_member_axis_ids():
    member_axis_ids = (
        "member_axis:XAUUSD:LONG:origin_liquidity_sweep_reclaim",
        "member_axis:XAUUSD:LONG:scheduler_lifecycle_core",
    )
    row = _sign_reduced_new_entry_row(
        {
            "candidate_id": "signed-member-axis-binding",
            "decision_time_utc": "2026-06-04T00:12:00+00:00",
            "symbol": "XAUUSD",
            "side": "LONG",
            "selector_action": "open-reduced-risk",
            "selector_reason": (
                "ultimate_candidate_package_admission_softened_selector_fill_floor_in_replay"
            ),
            "expected_net_r": 1.05,
            "probability": 0.86,
            "fill_probability": 0.72,
            "predecision_limit_fillability_probability": 0.68,
            "source_completeness": 1.0,
            "ultimate_package_matched_member_axis_count": 99,
            "ultimate_package_admission_member_axis_match_count": 77,
            "ultimate_package_matched_member_axis_ids": list(reversed(member_axis_ids)),
            "ultimate_candidate_package_open_reduced_risk_authority": {
                "applies": True,
                "allowed": True,
                "authority_family": "fill_floor_softening",
            },
        }
    )
    authority_field = "ultimate_candidate_package_open_reduced_risk_authority"
    authority = row[authority_field]
    payload = authority["package_new_entry_authority_payload"]
    original_hash = authority[scheduler.PACKAGE_NEW_ENTRY_AUTHORITY_HASH_FIELD]

    assert payload["matched_member_axis_ids"] == member_axis_ids
    assert "ultimate_package_matched_member_axis_count" not in payload
    assert "ultimate_package_admission_member_axis_match_count" not in payload

    count_only_mutation = {
        **row,
        "ultimate_package_matched_member_axis_count": 1,
        "ultimate_package_admission_member_axis_match_count": 1,
    }
    assert scheduler.package_new_entry_authority_hash_sha256(
        count_only_mutation,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
        authority=authority,
    ) == original_hash
    assert scheduler.reduced_package_new_entry_authority_validation(
        count_only_mutation,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
    )["valid"] is True

    mutated_source_ids = {
        **row,
        "ultimate_package_matched_member_axis_ids": [
            member_axis_ids[0],
            "member_axis:XAUUSD:LONG:mutated_after_signing",
        ],
    }
    mutated_validation = scheduler.reduced_package_new_entry_authority_validation(
        mutated_source_ids,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
    )
    assert mutated_validation["valid"] is False
    assert "current_signed_member_axis_ids_mismatch" in mutated_validation["failures"]

    removed_source_ids = dict(row)
    removed_source_ids.pop("ultimate_package_matched_member_axis_ids")
    removed_validation = scheduler.reduced_package_new_entry_authority_validation(
        removed_source_ids,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
    )
    assert removed_validation["valid"] is False
    assert "current_signed_member_axis_ids_mismatch" in removed_validation["failures"]

    tampered_payload_row = dict(row)
    tampered_authority = dict(authority)
    tampered_payload = dict(payload)
    tampered_payload["matched_member_axis_ids"] = (
        member_axis_ids[0],
        "member_axis:XAUUSD:LONG:tampered_payload",
    )
    tampered_authority["package_new_entry_authority_payload"] = tampered_payload
    tampered_payload_row[authority_field] = tampered_authority
    tampered_validation = scheduler.reduced_package_new_entry_authority_validation(
        tampered_payload_row,
        selector_action=row["selector_action"],
        selector_reason=row["selector_reason"],
        action_intent="new_position",
    )
    assert tampered_validation["valid"] is False
    assert "authority_hash_mismatch" in tampered_validation["failures"]


