def test_nested_broker_cost_packet_conflict_with_flat_refused_fails_closed():
    base = candidate(
        "nested-passed-flat-refused",
        "XAUUSD",
        ev_r=1.1,
        probability=0.82,
        fill_probability=0.78,
    )
    package_candidate = replace(
        base,
        metadata={
            **base.metadata,
            "pretrade_cost_packet_status": "REFUSED",
            "cost_source_gap_status": "SOURCE_GAP_COST_FALLBACK",
            "cost_authority": "timewarp_candidate_cost_proxy",
            "candidate_cost_r_fallback_is_authority": True,
            "pretrade_broker_net_cost_packet": {
                "status": "PASSED",
                "authority": "broker_calibrated_replay_cost",
                "cost_source_gap_status": "source_bound_cost_authority_present",
                "candidate_cost_r_fallback_is_authority": False,
                "total_cost_r": 0.07,
            },
        },
    )

    diagnostic = scheduler._candidate_broker_cost_rank_diagnostic(package_candidate)

    assert diagnostic["status"] == "broker_cost_rank_veto"
    assert diagnostic["hard_veto_reason"].startswith(
        "nested_broker_cost_packet_conflict_not_executable:"
    )
    assert diagnostic["pretrade_cost_packet_status"] == "PASSED"
    assert diagnostic["cost_authority"] == "broker_calibrated_replay_cost"
    assert diagnostic["cost_source_gap_status"] == "source_bound_cost_authority_present"
    assert diagnostic["candidate_cost_r_fallback_is_authority"] is False
    assert diagnostic["cost_packet_conflict_status"] == (
        "nested_broker_cost_packet_conflict_fail_closed"
    )
    assert set(diagnostic["cost_packet_conflict_fields"]) >= {
        "status",
        "cost_source_gap_status",
        "authority",
        "candidate_cost_r_fallback_is_authority",
    }


