def test_package_executable_authority_revalidates_with_configured_source_floor():
    base = candidate(
        "configured-source-floor",
        "AUDJPY",
        ev_r=1.18,
        probability=0.88,
        fill_probability=0.90,
    )
    locked = replace(
        base,
        expected_net_r=1.12,
        source_completeness=0.70,
        source_completeness_status="complete",
        metadata={
            **base.metadata,
            **_candidate_quality_metadata(),
            "package_replay_source_bound_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed": False,
            "package_replay_executable_candidate_use_allowed_reason": (
                "source_completeness_below_floor:0.700000"
            ),
            "source_bound_package_candidate_use_allowed": True,
            "ultimate_package_admission_sleeve_match_count": 1,
            "ultimate_package_matched_member_axis_ids": [
                "scheduler_lifecycle_core|AUDJPY|LONG"
            ],
        },
    )
    broker_cost_rank = {
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "hard_veto_reason": None,
    }

    default_allowed, default_reason, _ = scheduler._candidate_package_executable_authority(
        locked,
        broker_cost_rank,
    )
    configured_allowed, configured_reason, configured_source = (
        scheduler._candidate_package_executable_authority(
            locked,
            broker_cost_rank,
            source_completeness_floor=0.65,
        )
    )

    assert default_allowed is False
    assert "source_completeness_missing_or_degraded" in default_reason
    assert configured_allowed is True
    assert configured_reason == "derived_predecision_quality_source_and_broker_cost_authority"
    assert configured_source == "derived_after_selector_reduce_risk_materialization_self_lock"
    assert (
        scheduler._candidate_execution_authority_vetoes(
            locked,
            broker_cost_rank,
            source_completeness_floor=0.65,
        )
        == ()
    )


