def test_full_window_allocator_selects_best_candidate_and_preserves_all_options():
    window = DecisionWindow(
        decision_window_id="window:two-candidates",
        candidate_set_id="set:two-candidates",
        asof_utc="2026-06-04T00:00:00+00:00",
        candidates=(
            candidate("weak", "EURUSD", ev_r=0.1, probability=0.52),
            candidate("strong", "XAUUSD", ev_r=1.0, probability=0.72),
        ),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=1.0,
        same_decision_cluster_burst_guard_enabled=False,
    )

    assert packet["decision"]["selected_candidate_id"] == "strong"
    assert packet["decision"]["selected_action_class"] == "new_position"
    assert packet["runtime_effect_now"] is False
    assert packet["broker_operation"] is False
    assert packet["order_calls"] == 0
    assert packet["paid_api_or_vendor_call"] is False
    assert packet["input_counts"] == {
        "candidate_rows": 2,
        "open_positions": 0,
        "pending_orders": 0,
        "allocator_options": 3,
        "rejected_alternatives": 2,
    }
    assert {row["candidate_id"] for row in packet["all_options_preserved"]} >= {
        "weak",
        "strong",
        None,
    }


def test_selected_policy_expected_net_calibration_required_blocks_new_risk_trade():
    leaking_trade = replace(
        candidate("uncalibrated-selected-policy-trade", "XAUUSD", ev_r=1.30, probability=0.94),
        expected_net_r=1.25,
        fill_probability=0.92,
        selector_action="trade",
        selector_reason="broker_net_probability_confluence_lifecycle_admission_passed",
        metadata={
            **_candidate_quality_metadata(),
            "selected_policy": "momentum_exhaustion",
            "expected_net_r_selected_policy": "source_bound_proxy_not_policy_calibrated",
            "selected_policy_expected_net_calibration_status": (
                "selected_policy_expected_net_calibration_missing"
            ),
            "selected_policy_expected_net_calibration_source": (
                "packets.candidate_expected_net_r"
            ),
            "selected_policy_expected_net_calibration_source_boundary": (
                "selected_policy_expected_net_uncalibrated_bridge_proxy_predecision_quality"
            ),
            "pretrade_cost_packet_status": "PASSED",
            "cost_source_gap_status": "source_bound_cost_authority_present",
            "cost_authority": "broker_calibrated_replay_cost",
        },
    )
    window = DecisionWindow(
        decision_window_id="window:selected-policy-calibration-required",
        candidate_set_id="set:selected-policy-calibration-required",
        asof_utc="2026-06-04T00:00:00+00:00",
        candidates=(leaking_trade,),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=1.0,
        dynamic_budget_quality_gate_enabled=False,
        selected_policy_expected_net_calibration_required_for_new_risk=True,
    )

    option = next(
        row
        for row in packet["all_options_preserved"]
        if row["candidate_id"] == "uncalibrated-selected-policy-trade"
    )
    assert option["selected_policy_for_expected_net_r"] == "momentum_exhaustion"
    assert option["selected_policy_expected_net_calibration_required"] is True
    assert option["selected_policy_expected_net_calibrated"] is False
    assert any(
        "selected_policy_expected_net_calibration_missing" in veto
        for veto in option["vetoes"]
    )
    assert packet["decision"]["selected_action_class"] == "zero_trade"


