def _displacement_gate_option(
    candidate_id: str,
    *,
    selector_action: str,
    expected_net_r: float,
    probability: float,
    fill_probability: float,
    package_soft_authority: bool,
    origin_family: str = "origin_liquidity_sweep_reclaim",
    execution_fill_probability: float | None = None,
    signed_authority_valid: bool = True,
    signed_authority_status: str | None = None,
    signed_authority_failures: list[str] | None = None,
    cost_status: str = "PASSED",
) -> AllocatorOption:
    decision_inputs = {
        "candidate_id": candidate_id,
        "selector_action": selector_action,
        "expected_net_r": expected_net_r,
        "candidate_probability": probability,
        "candidate_fill_probability": fill_probability,
        "candidate_origin_family": origin_family,
        "origin_family": origin_family,
        "current_framework": origin_family,
        "source_completeness": 1.0,
        "pretrade_cost_packet_status": cost_status,
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
        "candidate_cost_r_fallback_is_authority": False,
    }
    execution_fill_probability = (
        fill_probability
        if execution_fill_probability is None and not package_soft_authority
        else execution_fill_probability
    )
    if execution_fill_probability is not None:
        decision_inputs.update(
            {
                "decision_time_utc": "2026-05-14T07:00:00+00:00",
                "execution_fill_probability": execution_fill_probability,
                "predecision_limit_fillability_probability": (
                    execution_fill_probability
                ),
                "limit_fillability_probability": execution_fill_probability,
                "execution_fill_probability_source": (
                    "predecision_limit_fillability.fill_probability"
                ),
                "execution_fill_probability_source_time_utc": (
                    "2026-05-14T06:45:00+00:00"
                ),
                "execution_fill_probability_source_boundary": (
                    "closed_m15_predecision_asof_no_postdecision_path"
                ),
                "execution_fill_probability_authority_class": (
                    "signed_predecision_execution_fillability_authority"
                ),
            }
        )
    score_components = {"candidate_decision_inputs": decision_inputs}
    if package_soft_authority:
        decision_inputs.update(
            {
                "package_open_reduced_authority_allowed": True,
                "package_open_reduced_authority_family": "router_refusal_softening",
                "ultimate_candidate_package_open_reduced_risk_authority": {
                    "allowed": True,
                    "authority_family": "router_refusal_softening",
                },
            }
        )
        score_components["selector_reduced_risk_new_position_signed_authority"] = {
            "required": True,
            "valid": signed_authority_valid,
            "status": signed_authority_status
            or (
                "valid_signed_predecision_new_entry_authority"
                if signed_authority_valid
                else "invalid_or_missing_signed_new_entry_authority"
            ),
            "failures": signed_authority_failures
            if signed_authority_failures is not None
            else (
                []
                if signed_authority_valid
                else ["invalid_or_missing_signed_new_entry_authority"]
            ),
        }
    return AllocatorOption(
        option_id=f"candidate:{candidate_id}",
        source_type="candidate",
        action_class="new_position",
        candidate_id=candidate_id,
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.25,
        approved_risk_pct=0.25,
        risk_delta_pct=0.25,
        score=max(0.01, expected_net_r),
        score_components=score_components,
        decision_status="candidate_ranked",
        reason="fixture",
        source_completeness=1.0,
        evidence_class="source_bound_decision_time_fixture",
    )


def test_package_soft_authority_displacement_gate_requires_signature_against_primary():
    primary = _displacement_gate_option(
        "clean-primary",
        selector_action="trade",
        expected_net_r=0.90,
        probability=0.86,
        fill_probability=0.92,
        package_soft_authority=False,
    )
    unsigned_package = _displacement_gate_option(
        "unsigned-package-dominates-primary",
        selector_action="open-reduced-risk",
        expected_net_r=1.80,
        probability=0.90,
        fill_probability=0.90,
        package_soft_authority=True,
        signed_authority_valid=False,
    )

    gated = scheduler._apply_package_soft_authority_displacement_gate(
        [unsigned_package, primary],
        SchedulerV4Config(
            package_soft_authority_displacement_quality_gate_enabled=True
        ),
    )
    row = next(
        option for option in gated if option.candidate_id == unsigned_package.candidate_id
    )
    diagnostic = row.score_components["package_displacement_quality"]

    assert diagnostic["allowed"] is False
    assert diagnostic["reason"] == (
        "signed_package_authority_invalid:"
        "invalid_or_missing_signed_new_entry_authority"
    )
    assert diagnostic["best_primary_candidate_id"] == "clean-primary"
    assert diagnostic["signed_new_entry_authority_valid"] is False
    assert diagnostic["signed_new_entry_authority_reason"] == (
        "invalid_or_missing_signed_new_entry_authority"
    )
    assert diagnostic["signed_new_entry_authority_failures"] == [
        "invalid_or_missing_signed_new_entry_authority"
    ]
    assert diagnostic["broker_cost_executable"] is True
    assert any(
        str(veto).startswith("package_soft_authority_displacement_quality_failed")
        for veto in row.vetoes
    )


def test_package_soft_authority_displacement_fails_closed_when_primary_value_missing() -> None:
    primary = _displacement_gate_option(
        "primary-without-executable-value",
        selector_action="trade",
        expected_net_r=0.90,
        probability=0.86,
        fill_probability=0.92,
        package_soft_authority=False,
    )
    primary_inputs = primary.score_components["candidate_decision_inputs"]
    primary_inputs.pop("expected_net_r")
    for key in (
        "execution_fill_probability",
        "predecision_limit_fillability_probability",
        "limit_fillability_probability",
        "execution_fill_probability_source",
        "execution_fill_probability_source_time_utc",
        "execution_fill_probability_source_boundary",
        "execution_fill_probability_authority_class",
    ):
        primary_inputs.pop(key, None)
    package = _displacement_gate_option(
        "signed-package-needs-real-primary-comparator",
        selector_action="open-reduced-risk",
        expected_net_r=1.20,
        probability=0.88,
        fill_probability=0.80,
        package_soft_authority=True,
    )

    gated = scheduler._apply_package_soft_authority_displacement_gate(
        [package, primary],
        SchedulerV4Config(
            package_soft_authority_displacement_quality_gate_enabled=True,
            package_soft_authority_displacement_allow_no_primary_comparator_authority=True,
        ),
    )
    row = next(option for option in gated if option.candidate_id == package.candidate_id)
    diagnostic = row.score_components["package_displacement_quality"]

    assert diagnostic["allowed"] is False
    assert diagnostic["reason"] == "primary_comparator_executable_value_missing"
    assert diagnostic["primary_comparator_candidate_count"] == 1
    assert diagnostic["primary_comparator_complete_value_count"] == 0
    assert diagnostic["primary_comparator_executable_value_missing"] is True
    assert diagnostic["zero_edge_floor_used"] is True
    assert diagnostic["runtime_eligible_after_rank_limit"] is False
    assert row.decision_status == "candidate_vetoed_package_displacement_quality_failed"


