    assert diagnostic["legacy_veto_family"] == "package_displacement_quality"
    assert diagnostic["fill_floor_quality_failure"] is True
    assert diagnostic["fill_floor_quality_failure_route_resolved"] is False
    assert diagnostic["fill_floor_quality_authority_unresolved"] is True
    assert (
        diagnostic["signed_new_entry_authority_effective_valid_for_displacement"]
        is False
    )
    assert row.decision_status == "candidate_vetoed_package_fill_floor_quality_failed"
    assert row.reason == (
        "package_fill_floor_quality_failed:"
        "package_fill_floor_authority_invalid:"
        "invalid_package_fill_floor_authority:"
        "package_fill_floor_quality_not_met:fill_probability"
    )
    assert any(
        str(veto).startswith("package_fill_floor_quality_failed:")
        for veto in row.vetoes
    )
    assert any(
        str(veto).startswith("package_soft_authority_displacement_quality_failed:")
        for veto in row.vetoes
    )
    record = row.to_record()
    assert record["decision_time_utc"] == "2026-05-13T00:15:00+00:00"
    assert record["cost_authority_status"] == "PASSED"
    assert record["selected_policy_expected_net_calibration_status"] == (
        "owner_approved_reconstructed_replay_selected_policy_expected_net_calibrated"
    )
    assert record["selected_policy_expected_net_calibration_source"] == (
        "owner_approved_reconstructed_proxy_package_expected_net_r"
    )
    assert record["predecision_limit_fillability_probability"] == 0.1559
    assert record["predecision_limit_fillability_source_boundary"] == (
        "closed_m15_predecision_asof_no_postdecision_path"
    )
    assert record["package_displacement_veto_family"] == "package_fill_floor_quality"
    assert record["package_displacement_fill_floor_quality_failure"] is True
    assert (
        record["package_displacement_fill_floor_quality_failure_route_resolved"]
        is False
    )
    assert record["package_displacement_fill_floor_quality_authority_unresolved"] is True


