    assert diagnostic["uses_outcome_fields"] is False
    assert soft["score_components"]["package_displacement_quality"] == diagnostic
    quality_priority = soft["package_authority_quality_priority"]
    assert quality_priority["tier"] == 1
    assert quality_priority["rank_limited_by_primary"] is True
    assert (
        quality_priority["reason"]
        == "package_soft_authority_rank_limited_below_primary_predecision_edge"
    )


