def test_no_primary_displacement_uses_absolute_edge_floor_not_comparator_delta_v230_shape():
    package = _displacement_gate_option(
        "v230-positive-low-fill-package",
        selector_action="open-reduced-risk",
        expected_net_r=1.311278304,
        probability=0.959459913,
        fill_probability=0.037322039,
        execution_fill_probability=0.037322039,
        package_soft_authority=True,
    )

    row = scheduler._apply_package_soft_authority_displacement_gate(
        [package],
        SchedulerV4Config(
            package_soft_authority_displacement_quality_gate_enabled=True,
            package_soft_authority_displacement_min_edge_delta=0.05,
            package_soft_authority_displacement_no_primary_min_edge_score=0.0,
            package_soft_authority_displacement_allow_no_primary_comparator_authority=True,
        ),
    )[0]
    diagnostic = row.score_components["package_displacement_quality"]

    assert 0.0 < diagnostic["candidate_edge_score"] < diagnostic["min_edge_delta"]
    assert diagnostic["primary_comparator_present"] is False
    assert diagnostic["edge_delta"] is None
    assert diagnostic["min_edge_delta_applies"] is False
    assert diagnostic["no_primary_min_edge_score"] == 0.0
    assert diagnostic["no_primary_min_edge_score_applies"] is True
    assert diagnostic["threshold_mode"] == "no_primary_absolute_expected_transfer_score"
    assert diagnostic["threshold_value"] == 0.0
    assert diagnostic["candidate_edge_positive"] is True
    assert diagnostic["allowed"] is True
    assert diagnostic["reason"] == (
        "no_primary_comparator_available_explicit_override_signed_package_"
        "edge_floor_allowed"
    )
    assert row.vetoes == ()
    record = row.to_record()
    assert record["package_displacement_primary_comparator_present"] is False
    assert record["package_displacement_edge_delta"] is None
    assert record["package_displacement_comparator_min_edge_delta"] == 0.05
    assert (
        record["package_displacement_comparator_min_edge_delta_applies"] is False
    )
    assert record["package_displacement_no_primary_min_edge_score"] == 0.0
    assert record["package_displacement_no_primary_min_edge_score_applies"] is True
    assert record["package_displacement_threshold_mode"] == (
        "no_primary_absolute_expected_transfer_score"
    )


