def test_window_headroom_reduced_new_entry_can_be_disabled():
    window = DecisionWindow(
        decision_window_id="window:reduced-headroom-disabled",
        candidate_set_id="set:reduced-headroom-disabled",
        asof_utc="2026-06-04T00:00:00+00:00",
        candidates=(
            candidate(
                "compressed-risk-entry",
                "XAUUSD",
                risk_pct=1.0,
                ev_r=1.2,
                probability=0.88,
                fill_probability=0.92,
            ),
        ),
    )

    legacy = packet_for(
        window,
        portfolio_ceiling_pct=0.50,
        min_reduced_risk_pct=0.10,
    )
    repaired = packet_for(
        window,
        portfolio_ceiling_pct=0.50,
        min_reduced_risk_pct=0.10,
        allow_window_headroom_reduced_new_entries=False,
    )

    assert legacy["decision"]["selected_candidate_id"] == "compressed-risk-entry"
    assert legacy["decision"]["selected_option"]["reason"] == (
        "risk_reduced_to_window_headroom"
    )
    assert repaired["decision"]["selected_action_class"] == "zero_trade"
    options = {row["candidate_id"]: row for row in repaired["all_options_preserved"]}
    rejected = options["compressed-risk-entry"]
    assert "window_headroom_reduced_new_entry_disabled" in rejected["vetoes"]
    assert (
        rejected["score_components"]["risk_headroom_diagnostic"][
            "allow_window_headroom_reduced_new_entries"
        ]
        is False
    )


