def test_reused_candidate_id_keeps_distinct_occurrences_through_option_joins():
    decision_time = "2026-06-04T09:15:00+00:00"
    strong = _source_stable_occurrence_row(
        "reused-lineage-id",
        "XAUUSD",
        decision_time=decision_time,
        entry_price=2400.0,
        stop_loss=2395.0,
        take_profit=2410.0,
        expected_net_r=1.40,
        probability=0.90,
        fill_probability=0.92,
    )
    weak = _source_stable_occurrence_row(
        "reused-lineage-id",
        "GBPUSD",
        decision_time=decision_time,
        entry_price=1.2700,
        stop_loss=1.2680,
        take_profit=1.2740,
        expected_net_r=0.55,
        probability=0.66,
        fill_probability=0.80,
    )
    packet = _mapping_packet([weak, strong], decision_time=decision_time)

    candidate_options = [
        row
        for row in packet["all_options_preserved"]
        if row["source_type"] == "new_candidate"
    ]
    assert len(candidate_options) == 2
    assert {row["option_id"] for row in candidate_options} == {
        f"candidate:{weak[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
        f"candidate:{strong[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
    }
    assert {row["symbol"] for row in candidate_options} == {"XAUUSD", "GBPUSD"}
    assert packet["decision"]["selected_option"]["symbol"] == "XAUUSD"
    assert any(
        row["symbol"] == "GBPUSD"
        for row in packet["rejected_alternatives"]
    )
    assert packet["input_counts"]["candidate_rows"] == 2
    assert packet["input_counts"]["allocator_options"] == 3


def test_public_mapping_collision_identity_survives_reorder_and_unrelated_insertion():
    decision_time = "2026-06-04T09:30:00+00:00"
    first = _source_stable_occurrence_row(
        "reused-tied-lineage-id",
        "EURUSD",
        decision_time=decision_time,
        entry_price=1.0800,
        stop_loss=1.0780,
        take_profit=1.0840,
        expected_net_r=1.0,
        probability=0.85,
        fill_probability=0.90,
    )
    second = _source_stable_occurrence_row(
        "reused-tied-lineage-id",
        "GBPUSD",
        decision_time=decision_time,
        entry_price=1.2700,
        stop_loss=1.2680,
        take_profit=1.2740,
        expected_net_r=1.0,
        probability=0.85,
        fill_probability=0.90,
    )
    unrelated = _source_stable_occurrence_row(
        "unrelated-candidate-id",
        "AUDUSD",
        decision_time=decision_time,
        entry_price=0.6600,
        stop_loss=0.6580,
        take_profit=0.6640,
        expected_net_r=0.25,
        probability=0.60,
        fill_probability=0.70,
    )

    forward = _mapping_packet([first, second], decision_time=decision_time)
    reversed_packet = _mapping_packet([second, first], decision_time=decision_time)
    inserted = _mapping_packet(
        [unrelated, second, first],
        decision_time=decision_time,
    )

    def reused_option_ids(packet: dict) -> dict[str, str]:
        return {
            row["symbol"]: row["option_id"]
            for row in packet["all_options_preserved"]
            if row.get("candidate_id") == "reused-tied-lineage-id"
        }

    expected_ids = reused_option_ids(forward)
    assert reused_option_ids(reversed_packet) == expected_ids
    assert reused_option_ids(inserted) == expected_ids
    assert set(expected_ids.values()) == {
        f"candidate:{first[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
        f"candidate:{second[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
    }
    selected_ids = {
        packet["decision"]["selected_option"]["option_id"]
        for packet in (forward, reversed_packet, inserted)
    }
    assert len(selected_ids) == 1
    assert selected_ids <= set(expected_ids.values())


def test_exact_duplicate_candidate_occurrences_are_both_preserved():
    decision_time = "2026-06-04T09:45:00+00:00"
    duplicate_a = _source_stable_occurrence_row(
        "exact-duplicate-lineage-id",
        "AUDUSD",
        decision_time=decision_time,
        entry_price=0.6600,
        stop_loss=0.6580,
        take_profit=0.6640,
        emission_ordinal=0,
        expected_net_r=1.0,
        probability=0.85,
        fill_probability=0.90,
    )
    duplicate_b = copy.deepcopy(duplicate_a)
    duplicate_b[CANDIDATE_EMISSION_ORDINAL_FIELD] = 1
    duplicate_b[CANDIDATE_EMISSION_ANCHOR_KEY_FIELD] = (
        candidate_emission_anchor_key(
            duplicate_b[CANDIDATE_SOURCE_LINEAGE_FINGERPRINT_FIELD],
            1,
        )
    )
    duplicate_b[CANDIDATE_OCCURRENCE_KEY_FIELD] = (
        candidate_occurrence_key_from_fields(duplicate_b)
    )
    assert duplicate_b[CANDIDATE_OCCURRENCE_KEY_FIELD]
    forward = _mapping_packet([duplicate_a, duplicate_b], decision_time=decision_time)
    reversed_packet = _mapping_packet(
        [duplicate_b, duplicate_a],
        decision_time=decision_time,
    )

    candidate_options = [
        row
        for row in forward["all_options_preserved"]
        if row["source_type"] == "new_candidate"
    ]
    assert len(candidate_options) == 2
    expected_ids = {
        f"candidate:{duplicate_a[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
        f"candidate:{duplicate_b[CANDIDATE_OCCURRENCE_KEY_FIELD]}",
    }
    assert {row["option_id"] for row in candidate_options} == expected_ids
    assert {
        row["option_id"]
        for row in reversed_packet["all_options_preserved"]
        if row["source_type"] == "new_candidate"
    } == expected_ids
    assert forward["decision"]["selected_option"]["option_id"] == (
        reversed_packet["decision"]["selected_option"]["option_id"]
    )
    assert sum(
        row["source_type"] == "new_candidate"
        for row in forward["rejected_alternatives"]
    ) == 1

    repeated_key_packet = _mapping_packet(
        [duplicate_a, copy.deepcopy(duplicate_a)],
        decision_time=decision_time,
    )
    repeated_key_options = [
        row
        for row in repeated_key_packet["all_options_preserved"]
        if row["source_type"] == "new_candidate"
    ]
    assert len(repeated_key_options) == 2
    assert all(
        row["decision_status"] == "candidate_occurrence_identity_not_evaluable"
        and "candidate_occurrence_key_not_unique_in_window"
        in row["score_components"]["candidate_occurrence_identity"]["failures"]
        for row in repeated_key_options
    )
    assert repeated_key_packet["decision"]["selected_action_class"] == "zero_trade"


def test_colliding_mapping_rows_without_occurrence_authority_fail_closed_individually():
    decision_time = "2026-06-04T10:00:00+00:00"
    first = {
        key: value
        for key, value in _source_stable_occurrence_row(
            "missing-occurrence-authority",
            "EURUSD",
            decision_time=decision_time,
            entry_price=1.0800,
            stop_loss=1.0780,
            take_profit=1.0840,
        ).items()
        if key
        not in {
            CANDIDATE_SOURCE_SAFE_FINGERPRINT_FIELD,
            CANDIDATE_EMISSION_ORDINAL_FIELD,
            CANDIDATE_OCCURRENCE_KEY_FIELD,
        }
    }
    second = copy.deepcopy(first)
    second.update(
        {
            "symbol": "GBPUSD",
            "entry_price": 1.2700,
            "entry_reference": 1.2700,
            "stop_loss": 1.2680,
            "stop_or_invalidation": 1.2680,
            "take_profit_1": 1.2740,
            "target_reference": 1.2740,
            "trade_parameters": {
                "direction": "LONG",
                "entry_price": 1.2700,
                "stop_loss": 1.2680,
                "take_profit_1": 1.2740,
                "risk_reward_ratio": 2.0,
            },
        }
    )

    packet = _mapping_packet([second, first], decision_time=decision_time)
    candidate_options = [
        row
        for row in packet["all_options_preserved"]
        if row["source_type"] == "new_candidate"
    ]
    assert len(candidate_options) == 2
    assert {row["option_id"] for row in candidate_options} == {
        "candidate:missing-occurrence-authority"
    }
    assert all(
        row["decision_status"] == "candidate_occurrence_identity_not_evaluable"
        and row["reason"] == "candidate_occurrence_identity_not_evaluable"
        and row["approved_risk_pct"] == 0.0
        and row["runtime_eligible"] is False
        and row["score_components"]["scheduler_materializable"] is False
        and row["score_components"]["runtime_order_executable_now"] is False
        and row["score_components"]["candidate_occurrence_identity"]["status"]
        == "NOT_EVALUABLE"
        for row in candidate_options
    )
    assert packet["decision"]["selected_action_class"] == "zero_trade"
    assert sum(
        row["source_type"] == "new_candidate"
        for row in packet["rejected_alternatives"]
    ) == 2


