def test_fillability_weight_can_repair_main_scheduler_ranking():
    window = DecisionWindow(
        decision_window_id="window:fillability-weight",
        candidate_set_id="set:fillability-weight",
        asof_utc="2026-06-04T00:00:00+00:00",
        candidates=(
            candidate(
                "slightly-higher-ev-unfillable",
                "EURUSD",
                ev_r=1.10,
                probability=0.66,
                fill_probability=0.10,
            ),
            candidate(
                "slightly-lower-ev-fillable",
                "GBPUSD",
                ev_r=0.84,
                probability=0.66,
                fill_probability=0.95,
            ),
        ),
    )

    default_packet = packet_for(window, portfolio_ceiling_pct=1.0)
    repaired_packet = packet_for(
        window,
        portfolio_ceiling_pct=1.0,
        fill_probability_score_weight=0.50,
    )

    assert default_packet["decision"]["selected_candidate_id"] == (
        "slightly-lower-ev-fillable"
    )
    assert repaired_packet["decision"]["selected_candidate_id"] == (
        "slightly-lower-ev-fillable"
    )
    default_selected = default_packet["decision"]["selected_option"]
    assert default_selected["score_components"]["fill_probability_score_weight"] == 0.1
    selected = repaired_packet["decision"]["selected_option"]
    assert selected["score_components"]["fill_probability_score_weight"] == 0.5


def test_scheduler_ranks_by_executable_transfer_not_raw_quality_diagnostics():
    common = {
        "symbol": "XAUUSD",
        "side": "LONG",
        "action_intent": "new_position",
        "requested_risk_pct": 0.25,
        "selector_action": "trade",
        "selector_reason": "clean_trade_authority",
        "execution_fill_probability_source": "predecision_limit_fillability",
        "confidence": 0.80,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "no_leak_status": "pass",
        "pretrade_cost_packet_status": "PASSED",
        "cost_source_gap_status": "source_bound_cost_authority_present",
        "cost_authority": "broker_calibrated_replay_cost",
        "candidate_decision_quality_field_sources": {
            "expected_net_r": "fixture.expected_net_r",
            "probability": "fixture.probability",
            "fill_probability": "fixture.fill_probability",
            "source_completeness": "fixture.source_completeness",
        },
        "candidate_decision_quality_alias_status": "exact_materialized",
        "candidate_decision_quality_source_boundary": (
            "predecision_fixture_quality_fields_no_outcome"
        ),
    }
    packet = build_scheduler_v4_packet(
        decision_window={
            "decision_window_id": "window:executable-transfer-ranking",
            "candidate_set_id": "set:executable-transfer-ranking",
            "asof_utc": "2026-06-04T00:00:00+00:00",
            "candidates": [
                {
                    **common,
                    "candidate_id": "higher-paper-edge-poor-execution-fill",
                    "expected_net_r": 1.30,
                    "candidate_probability": 0.95,
                    "candidate_fill_probability": 0.95,
                    "predecision_limit_fillability": {
                        "available": True,
                        "fill_probability": 0.20,
                        "current_price_source_time_utc": (
                            "2000-01-01T00:00:00+00:00"
                        ),
                        "source_boundary": (
                            "fixture_predecision_limit_fillability_no_outcome"
                        ),
                    },
                },
                {
                    **common,
                    "candidate_id": "lower-paper-edge-better-executable-transfer",
                    "expected_net_r": 0.85,
                    "candidate_probability": 0.80,
                    "candidate_fill_probability": 0.80,
                    "predecision_limit_fillability": {
                        "available": True,
                        "fill_probability": 0.90,
                        "current_price_source_time_utc": (
                            "2000-01-01T00:00:00+00:00"
                        ),
                        "source_boundary": (
                            "fixture_predecision_limit_fillability_no_outcome"
                        ),
                    },
                },
            ],
        },
        config={
            "enabled": True,
            "apply_to_execution": True,
            "portfolio_ceiling_pct": 1.0,
            "min_trade_score": 0.0,
            "zero_trade_score": 0.0,
            "executable_transfer_score_weight": 6.0,
            "execution_fill_shortfall_score_penalty_weight": 1.5,
        },
    )

    options = {row["candidate_id"]: row for row in packet["all_options_preserved"]}
    paper = options["higher-paper-edge-poor-execution-fill"]
    executable = options["lower-paper-edge-better-executable-transfer"]

    assert packet["decision"]["selected_candidate_id"] == (
        "lower-paper-edge-better-executable-transfer"
    )
    assert paper["score"] < executable["score"]
    assert paper["score_components"]["entry_quality_fill_probability"] == 0.95
    assert paper["score_components"]["execution_fill_probability"] == 0.20
    assert (
        paper["score_components"]["executable_transfer_component"]
        < executable["score_components"]["executable_transfer_component"]
    )
    assert paper["score_components"]["execution_fill_shortfall"] == 0.25
    contract = paper["score_components"]["score_sum_contract"]
    assert contract["numeric_diagnostics_excluded_from_score"] is True
    assert "execution_fill_probability" not in contract["summed_component_keys"]
    assert "fill_probability_score_weight" not in contract["summed_component_keys"]


