def test_reduced_package_new_entry_authority_requires_exact_broker_cost_authority():
    base_row = _sign_reduced_new_entry_row({
        "candidate_id": "package-cost-authority-exactness",
        "decision_time_utc": "2026-06-04T00:00:00+00:00",
        "symbol": "XAUUSD",
        "side": "LONG",
        "requested_risk_pct": 0.25,
        "ev_r": 1.10,
        "expected_net_r": 0.82,
        "probability": 0.76,
        "fill_probability": 0.92,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "selector_action": "reduce-risk",
        "selector_reason": "numeric_confluence_structured_disagreement",
        "ultimate_candidate_package_reduce_risk_authority": {
            "applies": True,
            "allowed": True,
            "authority_family": "numeric_disagreement_softening",
        },
    })

    cases = (
        (
            {"cost_authority": "timewarp_candidate_cost_proxy"},
            "broker_calibrated_cost_authority_unexpected:timewarp_candidate_cost_proxy",
        ),
        (
            {"cost_authority": "not_broker_calibrated_replay_cost"},
            "broker_calibrated_cost_authority_unexpected:not_broker_calibrated_replay_cost",
        ),
        (
            {"cost_source_gap_status": "SOURCE_GAP_COST_FALLBACK"},
            "source_bound_cost_authority_unexpected:source_gap_cost_fallback",
        ),
        (
            {"cost_source_gap_status": "source_bound_cost_authority_missing"},
            "source_bound_cost_authority_unexpected:source_bound_cost_authority_missing",
        ),
    )
    for mutation, expected_failure in cases:
        validation = scheduler.reduced_package_new_entry_authority_validation(
            {**base_row, **mutation},
            selector_action="reduce-risk",
            selector_reason="numeric_confluence_structured_disagreement",
            action_intent="new_position",
        )
        assert validation["valid"] is False
        assert expected_failure in validation["failures"]


