def test_allocator_option_record_preserves_raw_effective_selector_contract():
    option = AllocatorOption(
        option_id="candidate:raw-effective-contract",
        source_type="candidate",
        action_class="new_position",
        candidate_id="raw-effective-contract",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.1,
        approved_risk_pct=0.1,
        risk_delta_pct=0.1,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "selector_action": "open-reduced-risk",
                "selector_reason": (
                    "source_bound_router_refusal_open_reduced_materialized_for_replay"
                ),
                "selector_action_origin": "reject",
                "selector_reason_origin": (
                    "admission_quality_dynamic_router_refused_candidate_use"
                ),
                "effective_selector_action": "open-reduced-risk",
                "effective_selector_reason": (
                    "source_bound_router_refusal_open_reduced_materialized_for_replay"
                ),
                "materialized_selector_action": "open-reduced-risk",
            }
        },
        decision_status="candidate_ranked",
        reason="unit_test",
    )

    record = option.to_record()

    assert record["selector_action"] == "reject"
    assert record["raw_selector_action"] == "reject"
    assert record["selector_action_origin"] == "reject"
    assert record["effective_selector_action"] == "open-reduced-risk"
    assert record["materialized_selector_action"] == "open-reduced-risk"
    assert record["selector_action_semantics"] == (
        "selector_action_is_raw_selector_intent;"
        "effective_selector_action_is_materialized_runtime_action"
    )


def _signed_marketable_guard_candidate(
    package_candidate: AllocatorCandidate,
    *,
    expected_net_r: float,
    expected_cost_r: float = 0.05,
) -> AllocatorCandidate:
    selector_reason = (
        "source_bound_router_refusal_open_reduced_materialized_for_replay"
    )
    decision_time = "2026-05-13T08:15:00+00:00"
    metadata = _signed_reduced_new_entry_metadata(
        {
            **dict(package_candidate.metadata),
            "candidate_id": package_candidate.candidate_id,
            "decision_time_utc": decision_time,
            "symbol": package_candidate.symbol,
            "side": package_candidate.side,
            "selector_action": "open-reduced-risk",
            "selector_reason": selector_reason,
            "expected_net_r": expected_net_r,
            "candidate_expected_net_r": expected_net_r,
            "probability": package_candidate.probability,
            "candidate_probability": package_candidate.probability,
            "fill_probability": package_candidate.fill_probability,
            "candidate_fill_probability": package_candidate.fill_probability,
            "source_completeness": package_candidate.source_completeness,
            "source_completeness_status": (
                package_candidate.source_completeness_status
            ),
            "cost_r": expected_cost_r,
            "expected_cost_r": expected_cost_r,
            "cost_total_r": expected_cost_r,
            "ultimate_candidate_package_open_reduced_risk_authority": {
                "allowed": True,
                "applies": True,
                "authority_family": "router_refusal_softening",
                "authority_source": (
                    "derived_from_source_bound_router_refusal_package_authority"
                ),
                "selector_reason": selector_reason,
            },
            "ultimate_package_source_bound_candidate_use_allowed": True,
            "source_bound_package_candidate_use_allowed": True,
            "ultimate_package_admission_sleeve_match_count": 1,
        }
    )
    return replace(
        package_candidate,
        decision_time_utc=decision_time,
        expected_net_r=expected_net_r,
        selector_action="open-reduced-risk",
        selector_reason=selector_reason,
        metadata=metadata,
    )


