def test_equal_score_candidates_record_source_bound_tie_breaker_diagnostics():
    def executable_fixture(row):
        return AllocatorCandidate.from_mapping(
            _with_immutable_trade_execution_payload({
                "candidate_id": row.candidate_id,
                "decision_time_utc": "2026-06-04T00:05:00+00:00",
                "symbol": row.symbol,
                "side": row.side,
                "action_intent": row.action_intent,
                "requested_risk_pct": row.requested_risk_pct,
                "selected_cell_risk_pct": row.selected_cell_risk_pct,
                "ev_r": row.ev_r,
                "expected_net_r": row.ev_r,
                "probability": row.probability,
                "candidate_probability": row.probability,
                "confidence": row.confidence,
                "candidate_confidence": row.confidence,
                "scheduler_confidence": row.confidence,
                "uncertainty": row.uncertainty,
                "fill_probability": row.fill_probability,
                "candidate_fill_probability": row.fill_probability,
                "predecision_limit_fillability_probability": row.fill_probability,
                "execution_fill_probability": row.fill_probability,
                "execution_fill_probability_source": (
                    "predecision_limit_fillability"
                ),
                "source_completeness": row.source_completeness,
                "source_completeness_status": row.source_completeness_status,
                "evidence_class": row.evidence_class,
                "no_leak_status": row.no_leak_status,
                "confluence_action": row.confluence_action,
                "confluence_strength": row.confluence_strength,
                "confluence_confidence": row.confluence_confidence,
                "confluence_reliability": row.confluence_reliability,
                "cost_r": row.cost_r,
                "source_bound_package_candidate_use_allowed": True,
                "ultimate_package_source_bound_candidate_use_allowed": True,
                "ultimate_package_matched_member_axis_count": 1,
                "ultimate_package_admission_member_axis_match_count": 1,
                "ultimate_package_matched_member_axis_ids": [
                    f"fixture-member-axis:tie:{row.candidate_id}"
                ],
                "package_replay_candidate_use_allowed": True,
                "package_replay_executable_candidate_use_allowed": True,
                "package_replay_order_executable_candidate_use_allowed": True,
                "package_replay_order_executable_transfer_status": "order_bound",
                "package_replay_order_executable_bound_order_id": (
                    f"order:{row.candidate_id}"
                ),
            })
        )

    window = DecisionWindow(
        decision_window_id="window:score-tie",
        candidate_set_id="set:score-tie",
        asof_utc="2026-06-04T00:05:00+00:00",
        candidates=(
            executable_fixture(
                candidate("first", "EURUSD", ev_r=0.8, probability=0.65)
            ),
            executable_fixture(
                candidate("second", "GBPUSD", ev_r=0.8, probability=0.65)
            ),
        ),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=1.0,
        same_decision_cluster_burst_guard_enabled=False,
    )
    diagnostics = packet["decision"]["tie_breaker_diagnostics"]

    assert packet["decision"]["selected_candidate_id"] == "first"
    assert diagnostics == packet["tie_breaker_diagnostics"]
    assert diagnostics["tie_break_rule"] == (
        "replacement_reallocation_quality_desc_then_expected_transfer_desc_"
        "score_desc_then_lifecycle_risk_cleanup_priority_desc_"
        "non_zero_preferred_then_lower_input_sequence"
    )
    assert diagnostics["selected_primary_package_authority_quality_priority_tier"] == 0
    assert diagnostics["selected_primary_authority_priority_tier"] == 0
    assert diagnostics["selected_primary_replacement_reallocation_quality_score"] > 0.0
    assert diagnostics["selected_primary_expected_transfer_score"] > 0.0
    assert diagnostics["selected_primary_lifecycle_risk_cleanup_priority"] == 0
    assert diagnostics["selected_primary_replacement_release_tiebreak_score"] == 0.0
    assert diagnostics["package_authority_quality_priority_applied"] is False
    assert diagnostics["authority_priority_applied"] is False
    assert diagnostics["authority_priority_policy"] == "diagnostic_only_not_sort_value"
    assert diagnostics["replacement_release_tiebreak_policy"] == (
        "diagnostic_only_not_sort_value"
    )
    assert diagnostics["diagnostic_uses_outcome_fields"] is False
    assert diagnostics["outcome_fields_used"] == []
    assert diagnostics["selected_tie_group_size"] == 2
    assert diagnostics["selected_tie_group_candidate_ids"] == ["first", "second"]
    assert diagnostics["selected_tie_breaker"] == "lower_input_sequence"
    assert diagnostics["score_tie_group_count"] == 1


def test_transfer_different_candidates_are_not_reported_as_raw_score_ties():
    high_transfer = AllocatorOption(
        option_id="candidate:high-transfer",
        source_type="candidate",
        action_class="new_position",
        candidate_id="high-transfer",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.25,
        approved_risk_pct=0.25,
        risk_delta_pct=0.25,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "expected_net_r": 0.90,
                "probability": 0.90,
                "fill_probability": 0.90,
                **_strict_execution_fillability_fields(0.90),
                "source_completeness": 1.0,
            }
        },
        decision_status="candidate_ranked",
        reason="unit_test",
        input_sequence=0,
    )
    low_transfer = AllocatorOption(
        option_id="candidate:low-transfer",
        source_type="candidate",
        action_class="new_position",
        candidate_id="low-transfer",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.25,
        approved_risk_pct=0.25,
        risk_delta_pct=0.25,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "expected_net_r": 1.20,
                "probability": 0.90,
                "fill_probability": 0.90,
                **_strict_execution_fillability_fields(0.90),
                "source_completeness": 0.10,
            }
        },
        decision_status="candidate_ranked",
        reason="unit_test",
        input_sequence=1,
    )

    diagnostics = scheduler._score_tie_breaker_diagnostics(
        ordered=[high_transfer, low_transfer],
        selected_options=[high_transfer],
    )

    assert diagnostics["score_tie_group_count"] == 0
    assert diagnostics["selected_tie_group_size"] == 1
    assert diagnostics["selected_tie_breaker"] == (
        "replacement_reallocation_quality_or_expected_transfer_unique"
    )
    assert "replacement_reallocation_quality_desc" in diagnostics["tie_break_rule"]
    assert "expected_transfer_desc" in diagnostics["tie_break_rule"]


def test_replacement_release_bonus_does_not_outrank_higher_transfer_candidate():
    high_transfer = AllocatorOption(
        option_id="candidate:higher-transfer",
        source_type="candidate",
        action_class="new_position",
        candidate_id="higher-transfer",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.25,
        approved_risk_pct=0.25,
        risk_delta_pct=0.25,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "expected_net_r": 1.20,
                "probability": 0.90,
                "fill_probability": 0.90,
                **_strict_execution_fillability_fields(0.90),
                "source_completeness": 1.0,
            }
        },
        decision_status="candidate_ranked",
        reason="unit_test",
        input_sequence=1,
    )
    lower_transfer_replace = AllocatorOption(
        option_id="candidate:lower-transfer-replace",
        source_type="candidate",
        action_class="replace_pending",
        candidate_id="lower-transfer-replace",
        exposure_id=None,
        pending_id="pending-old",
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.25,
        approved_risk_pct=0.25,
        risk_delta_pct=0.25,
        score=1.0,
        score_components={
            "candidate_decision_inputs": {
                "expected_net_r": 0.80,
                "probability": 0.90,
                "fill_probability": 0.90,
                **_strict_execution_fillability_fields(0.90),
                "source_completeness": 1.0,
            },
            "pending_replacement_diagnostic": {
                "pending_replacement_causal_quality_gate_status": "passed",
                "release_candidates": [
                    {
                        "pending_id": "pending-old",
                        "pending_replacement_causal_quality_gate_status": "passed",
                        "release_reason": "unit_test_release",
                        "pending_replacement_causal_quality_gate": {
                            "expected_net_delta": 5.0,
                        },
                        "expected_net_delta": 5.0,
                        "fill_probability_delta": 1.0,
                        "source_completeness_delta": 1.0,
                        "expected_cost_delta": -1.0,
                        "risk_pct_delta": -1.0,
                        "reserved_risk_pct": 1.0,
                    }
                ],
            },
        },
        decision_status="candidate_ranked",
        reason="unit_test",
        input_sequence=0,
    )

    high_diag = scheduler._option_replacement_reallocation_quality_diagnostic(
        high_transfer
    )
    replace_diag = scheduler._option_replacement_reallocation_quality_diagnostic(
        lower_transfer_replace
    )
    high_with_diag = scheduler._with_replacement_reallocation_quality(
        high_transfer, high_diag
    )
    replace_with_diag = scheduler._with_replacement_reallocation_quality(
        lower_transfer_replace, replace_diag
    )

    ordered = sorted(
        [replace_with_diag, high_with_diag],
        key=scheduler._scheduler_option_sort_key,
        reverse=True,
    )
    same_window_diagnostic = scheduler._same_window_reallocation_diagnostic(
        ordered_options=ordered,
        selected_options=[ordered[0]],
    )

    assert ordered[0].candidate_id == "higher-transfer"
    assert same_window_diagnostic[
        "best_same_window_executable_comparator_candidate_id"
    ] == "higher-transfer"
    assert same_window_diagnostic[
        "reallocation_blocked_by_better_executable_comparator"
    ] is False
    assert same_window_diagnostic[
        "same_window_executable_comparator_source_boundary"
    ] == "predecision_runtime_eligible_order_executable_transfer_status_no_outcome_fields"
    assert replace_diag["replacement_release_bonus"] > 0.0
    assert replace_diag["replacement_release_value_contribution"] == 0.0
    assert replace_diag["replacement_release_score_policy"] == (
        "diagnostic_only_not_transfer_or_sort_value"
    )
    assert replace_diag["score"] == replace_diag[
        "risk_cap_adjusted_expected_transfer_score"
    ]
    assert scheduler._option_replacement_release_tiebreak_score(
        replace_with_diag
    ) > 0.0


def test_same_symbol_duplicate_is_vetoed_but_ticket_bound_scale_in_can_win():
    open_gold = OpenExposure(
        exposure_id="open:xau",
        ticket="123",
        symbol="XAUUSD",
        side="LONG",
        risk_pct=0.25,
        thesis_id="thesis:gold-base",
        source_completeness=1.0,
    )
    duplicate = candidate("duplicate", "XAUUSD", action_intent="new_position", ev_r=2.0)
    scale = candidate(
        "scale",
        "XAUUSD",
        action_intent="same_direction_scale_in",
        ev_r=1.2,
        thesis_improvement=0.25,
    )
    window = DecisionWindow(
        decision_window_id="window:same-symbol",
        candidate_set_id="set:same-symbol",
        asof_utc="2026-06-04T00:15:00+00:00",
        candidates=(duplicate, scale),
        open_positions=(open_gold,),
    )

    packet = packet_for(window, portfolio_ceiling_pct=1.0)
    duplicate_row = next(
        row for row in packet["all_options_preserved"] if row["candidate_id"] == "duplicate"
    )

    assert packet["decision"]["selected_candidate_id"] == "scale"
    assert packet["decision"]["selected_action_class"] == "same_direction_scale_in"
    assert "same_symbol_duplicate_requires_lifecycle_scale_or_replace" in duplicate_row["vetoes"]
    assert packet["exposure_snapshot"]["same_symbol_risk_pct"]["XAUUSD"] == 0.25


