def test_hazard_ineligible_leader_does_not_consume_transactional_burst_slot(
    monkeypatch,
):
    window = DecisionWindow(
        decision_window_id="window:transactional-burst-after-hazard",
        candidate_set_id="set:transactional-burst-after-hazard",
        asof_utc="2026-06-04T00:19:00+00:00",
        candidates=(
            candidate("hazard-leader", "AUDJPY", ev_r=1.40, probability=0.80, risk_pct=1.0),
            candidate("clean-follower", "GBPJPY", ev_r=1.20, probability=0.74, risk_pct=1.0),
        ),
    )
    original_score = scheduler._option_hazard_adjusted_executable_quality_score

    def hazard_adjusted_score(option, *args, **kwargs):
        if option.candidate_id == "hazard-leader":
            return -0.05
        return original_score(option, *args, **kwargs)

    monkeypatch.setattr(
        scheduler,
        "_option_hazard_adjusted_executable_quality_score",
        hazard_adjusted_score,
    )

    packet = packet_for(
        window,
        allow_multiple_new_positions_per_window=True,
        portfolio_ceiling_pct=4.0,
        correlation_cluster_ceiling_pct=4.0,
    )

    assert packet["decision"]["selected_candidate_ids"] == ["clean-follower"]
    options = {row["candidate_id"]: row for row in packet["all_options_preserved"]}
    follower_burst = options["clean-follower"]["score_components"][
        "same_decision_cluster_burst_guard"
    ]
    assert follower_burst["blocked"] is False
    assert follower_burst["prior_same_cluster_side_new_position_count"] == 0
    assert follower_burst["capacity_accounting_stage"] == "transactional_final_selection"


