def _open_reduced_passive_limit_route_row(overrides: dict | None = None) -> dict:
    row = {
        "candidate_id": "open-reduced-passive-limit-route",
        "symbol": "XAUUSD",
        "side": "LONG",
        "requested_risk_pct": 0.25,
        "selected_cell_risk_pct": 0.25,
        "ev_r": 1.10,
        "expected_net_r": 1.02,
        "candidate_probability": 0.88,
        "confidence": 0.84,
        "candidate_confidence": 0.84,
        "scheduler_confidence": 0.84,
        "candidate_fill_probability": 0.95,
        "source_completeness": 1.0,
        "source_completeness_status": "complete",
        "selected_policy": "momentum_exhaustion",
        "expected_net_r_selected_policy": "momentum_exhaustion",
        "selected_policy_expected_net_calibration_status": "calibrated",
        "no_leak_status": "pass",
        "selector_action": "open-reduced-risk",
        "selector_reason": (
            "ultimate_candidate_package_admission_softened_selector_fill_floor_in_replay"
        ),
        "ultimate_candidate_package_open_reduced_risk_authority": {
            "applies": True,
            "allowed": True,
            "authority_family": "fill_floor_softening",
        },
        "ultimate_package_matched_sleeve_count": 3,
        "ultimate_package_admission_sleeve_match_count": 2,
        "ultimate_package_role_disposition": "scheduler_lifecycle_core",
        "ultimate_package_combined_source_bound_signal_r_sum": 88.0,
        "predecision_limit_fillability": {
            "available": True,
            "limit_marketable_at_decision": False,
            "fill_probability": 0.14,
            "distance_to_limit_risk": 0.50,
        },
        "would_guarded_market_fallback": "guarded_market_after_fillability_cost_proof",
        "cost_r": 0.05,
    }
    if overrides:
        row.update(overrides)
        if "predecision_limit_fillability" not in overrides:
            override_limit_fill = next(
                (
                    overrides.get(field)
                    for field in (
                        "predecision_limit_fillability_probability",
                        "limit_fillability_probability",
                        "execution_fill_probability",
                    )
                    if overrides.get(field) not in (None, "")
                ),
                None,
            )
            if override_limit_fill is not None:
                row["predecision_limit_fillability"] = {
                    **row["predecision_limit_fillability"],
                    "fill_probability": override_limit_fill,
                }
    return _sign_reduced_new_entry_row(row)


