def test_candidate_option_defers_open_reduced_priority_until_window_context():
    config = SchedulerV4Config.from_mapping(_passive_limit_route_config())
    window = DecisionWindow.from_mapping(
        {
            "decision_window_id": "window:open-reduced-priority-pending",
            "candidate_set_id": "set:open-reduced-priority-pending",
            "asof_utc": "2026-06-04T00:25:00+00:00",
            "candidates": [_open_reduced_passive_limit_route_row()],
        }
    )
    snapshot = scheduler.build_exposure_snapshot(window, config)

    option = scheduler._candidate_option(  # noqa: SLF001 - verifies pre-context contract
        window.candidates[0],
        snapshot,
        config,
    )

    priority = option.score_components["scheduler_authority_priority_tier"]
    assert priority["tier"] == 0
    assert priority["reason"] == (
        "selector_reduced_new_entry_pending_primary_trade_competitor_context"
    )
    assert priority["pending_primary_trade_competitor_context"] is True
    assert priority["primary_trade_competitor_fallback_reason"] == (
        "selector_reduced_new_entry_fallback_after_primary_trade_authority"
    )
    assert priority["eligible_primary_trade_competitor_present"] is None


