def test_stop_hazard_configured_cap_does_not_reduce_transfer_without_effective_cap():
    decision_inputs = {
        "expected_net_r": 2.0,
        "candidate_probability": 0.80,
        "candidate_fill_probability": 0.90,
        "source_completeness": 1.0,
        "requested_risk_pct": 0.625,
        "selected_cell_risk_pct": 0.625,
        "predecision_stop_hazard_guard_status": "passed",
        "predecision_stop_hazard_guard_action": "cap",
        "predecision_stop_hazard_guard_configured_action": "cap",
        "predecision_stop_hazard_guard_effective_action": "no_block",
        "predecision_stop_hazard_guard_effective_cap": False,
        "predecision_stop_hazard_guard_risk_cap_applied": False,
        "predecision_stop_hazard_guard_risk_cap_pct": 0.10,
    }
    option = AllocatorOption(
        option_id="candidate:configured-cap-passed",
        source_type="candidate",
        action_class="new_position",
        candidate_id="configured-cap-passed",
        exposure_id=None,
        pending_id=None,
        symbol="XAUUSD",
        side="LONG",
        requested_risk_pct=0.625,
        approved_risk_pct=0.625,
        risk_delta_pct=0.625,
        score=1.0,
        score_components={
            "candidate_decision_inputs": decision_inputs,
            "predecision_stop_hazard_guard": {
                "status": "passed",
                "action": "cap",
                "configured_action": "cap",
                "effective_action": "no_block",
                "risk_cap_applied": False,
                "risk_cap_pct": 0.10,
            },
        },
        decision_status="candidate",
        reason="fixture",
    )

    transfer = scheduler._option_expected_transfer_score(option)
    diagnostic = scheduler._option_replacement_reallocation_quality_diagnostic(option)

    assert scheduler._option_stop_hazard_risk_cap_factor(option) == 1.0
    assert diagnostic["risk_cap_transfer_factor"] == 1.0
    assert diagnostic["risk_cap_adjusted_expected_transfer_score"] == round(
        transfer,
        9,
    )


