def test_cluster_headroom_absent_is_reported_with_specific_diagnostics():
    open_silver = OpenExposure(
        exposure_id="open:xag",
        ticket="321",
        symbol="XAGUSD",
        side="LONG",
        risk_pct=2.0,
        thesis_id="thesis:silver-parent",
        source_completeness=1.0,
    )
    gold = candidate("gold", "XAUUSD", ev_r=1.0, probability=0.72, risk_pct=2.0)
    window = DecisionWindow(
        decision_window_id="window:cluster-headroom",
        candidate_set_id="set:cluster-headroom",
        asof_utc="2026-06-04T00:20:00+00:00",
        candidates=(gold,),
        open_positions=(open_silver,),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=4.0,
        correlation_cluster_ceiling_pct=2.0,
    )
    gold_row = next(row for row in packet["all_options_preserved"] if row["candidate_id"] == "gold")
    diagnostic = gold_row["score_components"]["risk_headroom_diagnostic"]

    assert packet["decision"]["selected_action_class"] == "zero_trade"
    assert gold_row["reason"] == "cluster_risk_headroom_absent"
    assert gold_row["vetoes"] == ["cluster_risk_headroom_absent"]
    assert diagnostic["limiting_scope"] == "cluster"
    assert diagnostic["candidate_cluster_key"] == "metals"
    assert diagnostic["portfolio_headroom_pct"] == 2.0
    assert diagnostic["cluster_headroom_pct"] == 0.0
    assert diagnostic["max_allowed_new_risk_pct"] == 0.0
    assert diagnostic["combined_legacy_reason"] == "portfolio_or_cluster_risk_headroom_absent"


def test_high_edge_candidate_replaces_dominated_pending_risk_same_window():
    pending = PendingExposure(
        pending_id="pending:old-xau",
        symbol="XAUUSD",
        side="LONG",
        reserved_risk_pct=1.5,
        age_minutes=45,
        fill_probability=0.20,
        pending_fill_probability_authority_class="passive_limit_fillability",
        stale_thesis_score=0.10,
        ev_r=0.10,
        probability=0.52,
        cost_r=0.18,
        scheduler_score=0.12,
        source_completeness=1.0,
        metadata=_strict_execution_fillability_fields(
            0.20,
            decision_time_utc="2026-06-04T00:22:00+00:00",
        ),
    )
    strong = candidate(
        "gold-replacement",
        "XAUUSD",
        ev_r=1.25,
        probability=0.86,
        risk_pct=1.5,
    )
    strong = replace(
        strong,
        metadata={
            **strong.metadata,
            "predecision_limit_fillability_probability": strong.fill_probability,
        },
    )
    window = DecisionWindow(
        decision_window_id="window:pending-replacement",
        candidate_set_id="set:pending-replacement",
        asof_utc="2026-06-04T00:22:00+00:00",
        candidates=(strong,),
        pending_orders=(pending,),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=1.5,
        correlation_cluster_ceiling_pct=1.5,
    )
    selected = packet["decision"]["selected_option"]
    diagnostic = selected["score_components"]["pending_replacement_diagnostic"]
    headroom = selected["score_components"]["risk_headroom_diagnostic"]

    assert packet["decision"]["selected_candidate_id"] == "gold-replacement"
    assert packet["decision"]["selected_action_class"] == "replace_pending"
    assert packet["decision"]["selected_pending_id"] == "pending:old-xau"
    assert selected["approved_risk_pct"] == 1.5
    assert diagnostic["replacement_applied"] is True
    assert diagnostic["pending_replacement_causal_quality_gate_status"] == "passed"
    assert diagnostic["release_pending_ids"] == ["pending:old-xau"]
    assert diagnostic["portfolio_release_risk_pct"] == 1.5
    assert headroom["pending_replacement_applied"] is True
    assert headroom["effective_cluster_reserved_after_pending_replacement_pct"] == 0.0


def test_cross_asset_soft_reduce_risk_cannot_release_pending_or_scale_in_when_disabled():
    pending = PendingExposure(
        pending_id="pending:old-xau",
        symbol="XAUUSD",
        side="LONG",
        reserved_risk_pct=0.25,
        age_minutes=45,
        fill_probability=0.20,
        pending_fill_probability_authority_class="passive_limit_fillability",
        stale_thesis_score=0.10,
        ev_r=0.10,
        probability=0.52,
        cost_r=0.05,
        scheduler_score=0.12,
        source_completeness=1.0,
        metadata=_strict_execution_fillability_fields(
            0.20,
            decision_time_utc="2026-05-13T03:45:00+00:00",
        ),
    )
    base = candidate(
        "cross-asset-soft-row",
        "XAUUSD",
        side="LONG",
        ev_r=1.20,
        probability=0.88,
        risk_pct=0.25,
        fill_probability=0.95,
        thesis_improvement=0.0,
    )
    soft_row = replace(
        base,
        decision_time_utc="2026-05-13T03:45:00+00:00",
        selector_action="reduce-risk",
        selector_reason=(
            "ultimate_candidate_package_dynamic_router_refusal_softened_reduce_risk"
        ),
        expected_net_r=1.08,
        metadata={
            **base.metadata,
            "candidate_origin_family": "origin_cross_asset_lead_lag",
            "origin_family": "origin_cross_asset_lead_lag",
            "framework": "origin_cross_asset_lead_lag",
            "source_bound_package_candidate_use_allowed": True,
            "ultimate_package_source_bound_candidate_use_allowed": True,
            "ultimate_package_effective_source_bound_candidate_use_allowed": True,
            "ultimate_package_effective_admission_count": 1,
            "ultimate_package_effective_matched_count": 1,
            "ultimate_package_admission_sleeve_match_count": 1,
            "ultimate_package_matched_sleeve_count": 1,
            "package_replay_source_bound_candidate_use_allowed": True,
            "package_replay_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed": True,
            "package_replay_executable_candidate_use_allowed_reason": (
                "broker_cost_and_scheduler_action_executable"
            ),
            "ultimate_candidate_package_open_reduced_risk_authority": {
                "allowed": True,
                "authority_family": "router_refusal_softening",
                "selector_reason": (
                    "ultimate_candidate_package_dynamic_router_refusal_softened_reduce_risk"
                ),
            },
        },
    )
    window = DecisionWindow(
        decision_window_id="window:cross-asset-soft-block",
        candidate_set_id="set:cross-asset-soft-block",
        asof_utc="2026-05-13T03:45:00+00:00",
        candidates=(soft_row,),
        pending_orders=(pending,),
    )

    packet = packet_for(
        window,
        portfolio_ceiling_pct=0.25,
        correlation_cluster_ceiling_pct=0.25,
        pending_replacement_enabled=True,
        source_required_package_duplicate_scale_in_enabled=True,
        selector_reduce_risk_package_fill_floor_authority_enabled=True,
        selector_reduce_risk_router_refusal_package_new_entry_authority_enabled=False,
        selector_reduce_risk_cross_asset_lead_lag_soft_authority_enabled=False,
        selector_reduce_risk_package_fill_floor_min_expected_net_r=0.70,
        selector_reduce_risk_package_fill_floor_min_probability=0.70,
        selector_reduce_risk_package_fill_floor_min_fill_probability=0.25,
        selector_reduce_risk_package_fill_floor_min_source_completeness=0.65,
    )
    option = next(
        row
        for row in packet["all_options_preserved"]
        if row["candidate_id"] == "cross-asset-soft-row"
    )
    replacement = option["score_components"]["pending_replacement_diagnostic"]
    duplicate_scale = option["score_components"][
        "source_required_package_duplicate_scale_in_authority"
    ]
    selector_authority = option["score_components"][
        "selector_reduce_risk_new_entry_authority"
    ]

    assert replacement["replacement_applied"] is True
    assert replacement["runtime_replacement_applied"] is False
    assert replacement["runtime_release_pending_ids"] == []
    assert replacement["selector_reduce_risk_release_blocked"] is True
    assert any(
        "cross_asset_lead_lag_soft_authority_disabled" in failure
        for failure in replacement["selector_reduce_risk_release_failures"]
    )
    assert duplicate_scale["allowed"] is False
    assert any(
        "cross_asset_lead_lag_soft_authority_disabled" in failure
        for failure in duplicate_scale["failures"]
    )
    assert selector_authority["hard_block_reason"] == (
        "cross_asset_lead_lag_soft_authority_disabled"
    )
    assert option["runtime_eligible"] is False
    assert packet["decision"]["selected_action_class"] == "zero_trade"


