def test_pending_replacement_requires_material_candidate_edge():
    pending = PendingExposure(
        pending_id="pending:quality-xag",
        symbol="XAGUSD",
        side="LONG",
        reserved_risk_pct=1.5,
        age_minutes=30,
        fill_probability=0.82,
        stale_thesis_score=0.05,
        ev_r=0.80,
        probability=0.76,
        cost_r=0.05,
        scheduler_score=1.05,
        source_completeness=1.0,
        metadata=_strict_execution_fillability_fields(
            0.82,
            decision_time_utc="2026-06-04T00:23:00+00:00",
        ),
    )
    modest = candidate(
        "gold-modest",
        "XAUUSD",
        ev_r=0.70,
        probability=0.69,
        risk_pct=1.5,
    )
