def test_runtime_capture_missing_cost_and_source_hash_blocks_scheduler_authority():
    packet = build_scheduler_v4_runtime_capture_packet(
        candidate={"candidate_id": "cost-gap", "symbol": "EURUSD", "side": "LONG"},
        runtime_event={"timestamp_utc": "2026-06-04T02:05:00+00:00"},
        selected_cell_risk_packet={"risk_pct": 0.25, "cell_id": "risk:unit"},
        final_risk_authority={"effective_risk_pct": 0.25},
        source_context={
            "decision_window_candidates": [
                {
                    "candidate_id": "cost-gap",
                    "symbol": "EURUSD",
                    "side": "LONG",
                    "requested_risk_pct": 0.25,
                    "ev_r": 1.20,
                    "probability": 0.72,
                    "source_completeness": 1.0,
                    "source_completeness_status": "complete",
                    "no_leak_status": "pass",
                },
            ],
            "open_position_snapshot": [],
            "pending_order_snapshot": [],
            "same_symbol_lifecycle_packet": {"status": "complete"},
            "probability_debate_packet": {"status": "complete"},
            "numeric_follow_avoid_mixed_packet": {"status": "complete"},
            "selector_v4_packet": {"status": "complete", "action": "trade"},
            "zero_trade_value_calibration": {"status": "complete"},
            "source_completeness_state": "source_window_complete",
            "no_leak_status": "pass",
        },
        config={
            "enabled": True,
            "apply_to_execution": True,
            "live_activation_allowed": True,
            "require_full_window_source": True,
        },
    )

    assert packet["decision"]["selected_action_class"] == "zero_trade"
    assert packet["runtime_effect_now"] is False
    assert "pretrade_cost_model" in packet["source_boundary"]["missing_runtime_truth"]
    assert "source_event_hash" in packet["source_boundary"]["missing_runtime_truth"]
    candidate_row = next(
        row for row in packet["all_options_preserved"] if row["candidate_id"] == "cost-gap"
    )
    assert "scheduler_v4_full_window_source_required:pretrade_cost_model" in candidate_row[
        "vetoes"
    ]
    assert "scheduler_v4_full_window_source_required:source_event_hash" in candidate_row[
        "vetoes"
    ]


def test_exposure_snapshot_schema_carries_semantic_owner_dependencies():
    schema = build_open_pending_exposure_snapshot_schema()

    assert schema["schema_version"] == "scheduler_v4_open_pending_exposure_snapshot_v1"
    assert "same_symbol_same_instrument_lifecycle_v4" in schema["semantic_dependencies"]
    assert "probability_debate_team_engine_v4" in schema["semantic_dependencies"]
    assert "follow_avoid_mixed_numeric_confluence_v4" in schema["semantic_dependencies"]
    assert "Feature Store V2" in schema["semantic_dependencies"]


def test_agent_config_points_scheduler_v4_active_authority():
    with open("config/agent_config.yaml", encoding="utf-8") as handle:
        config = yaml.safe_load(handle)

    runtime = config["gtos_vnext_runtime"]
    assert runtime["scheduler_v4_best_trade_allocator_enabled"] is True
    assert runtime["scheduler_v4_best_trade_allocator_apply_to_execution"] is True
    assert runtime["scheduler_v4_best_trade_allocator_live_activation_allowed"] is False
    assert runtime["ultimate_candidate_package_live_activation_allowed"] is False
    assert runtime["ultimate_candidate_package_final_package_selected"] is False
    assert runtime[
        "scheduler_v4_best_trade_allocator_allow_multiple_new_positions_per_window"
    ] is True
    assert runtime["scheduler_v4_best_trade_allocator_pending_replacement_enabled"] is True
    assert runtime[
        "scheduler_v4_best_trade_allocator_pending_replacement_min_candidate_ev_r"
    ] == 0.65
    assert runtime[
        "scheduler_v4_best_trade_allocator_pending_replacement_min_candidate_probability"
    ] == 0.68
    assert runtime["scheduler_v4_best_trade_allocator_require_full_window_source"] is True
    assert runtime["scheduler_v4_best_trade_allocator_route_manifest_path"].endswith(
        "WAVE3_OUTPUT_MANIFEST.json"
    )
